-- ---------------------------------------------------------------------------
-- Meet Millions Finance CRM — the full schema, all 13 migrations in order.
--
-- GENERATED by scripts/bundle-migrations.mjs. Do not edit by hand; edit the
-- files in database/migrations/ and regenerate.
--
-- This exists for one situation: applying the schema to a brand-new, empty D1
-- database through the Cloudflare dashboard console, where there is no CLI.
-- The supported path is still
--
--     npm run db:migrate:remote
--
-- which records each file in d1_migrations so later migrations apply cleanly.
--
-- THIS FILE DOES NOT WRITE d1_migrations. Wrangler will therefore believe none
-- of these migrations has run, and a later db:migrate:remote will try to apply
-- all of them again against tables that already exist, and fail. If you paste
-- this, keep using the dashboard for subsequent schema changes, or reconcile
-- d1_migrations by hand before going back to the CLI.
--
-- Apply to an EMPTY database only.
-- ---------------------------------------------------------------------------

-- ===== 0001_identity_and_tenancy.sql =====

-- =============================================================================
-- 0001 — Identity, tenancy and security
-- =============================================================================
-- Conventions used across every migration in this project:
--   * Primary keys are TEXT (ULID-style, generated in `src/utils/id.js`).
--   * Timestamps are TEXT, ISO-8601 UTC — lexicographically sortable.
--   * Money is INTEGER *paise*. Never a float: a finance ledger must not drift.
--   * Every tenant-scoped table carries tenant_id and indexes it first.
-- =============================================================================

PRAGMA foreign_keys = ON;

-- --------------------------------------------------------------------------
-- Tenants — one row per firm/account on the platform. The isolation boundary.
-- --------------------------------------------------------------------------
CREATE TABLE tenants (
  id                TEXT PRIMARY KEY,
  name              TEXT NOT NULL,
  slug              TEXT NOT NULL UNIQUE,
  legal_name        TEXT,
  email             TEXT NOT NULL,
  phone             TEXT,
  address_line1     TEXT,
  address_line2     TEXT,
  city              TEXT,
  state             TEXT,
  state_code        TEXT,               -- GST state code, drives CGST/SGST vs IGST
  pincode           TEXT,
  country           TEXT NOT NULL DEFAULT 'IN',
  gstin             TEXT,
  pan               TEXT,
  tan               TEXT,
  status            TEXT NOT NULL DEFAULT 'active'
                      CHECK (status IN ('active','trial','suspended','cancelled')),
  timezone          TEXT NOT NULL DEFAULT 'Asia/Kolkata',
  currency          TEXT NOT NULL DEFAULT 'INR',
  franchise_id      TEXT,               -- set when this tenant belongs to a franchise
  is_demo           INTEGER NOT NULL DEFAULT 0,
  onboarding_step   TEXT NOT NULL DEFAULT 'complete',
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL,
  deleted_at        TEXT
);
CREATE INDEX idx_tenants_status ON tenants(status);
CREATE INDEX idx_tenants_franchise ON tenants(franchise_id);

-- --------------------------------------------------------------------------
-- Franchises — a network operator owning several tenants (add-on 26).
-- --------------------------------------------------------------------------
CREATE TABLE franchises (
  id                  TEXT PRIMARY KEY,
  name                TEXT NOT NULL,
  code                TEXT NOT NULL UNIQUE,
  owner_name          TEXT,
  owner_email         TEXT,
  owner_phone         TEXT,
  city                TEXT,
  state               TEXT,
  status              TEXT NOT NULL DEFAULT 'onboarding'
                        CHECK (status IN ('onboarding','active','suspended','terminated')),
  revenue_share_pct   REAL NOT NULL DEFAULT 20.0,
  branding_json       TEXT,             -- franchise-level white-label overrides
  onboarded_at        TEXT,
  created_at          TEXT NOT NULL,
  updated_at          TEXT NOT NULL
);

-- --------------------------------------------------------------------------
-- Branches — offices within a tenant (add-on 25).
-- --------------------------------------------------------------------------
CREATE TABLE branches (
  id            TEXT PRIMARY KEY,
  tenant_id     TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  name          TEXT NOT NULL,
  code          TEXT NOT NULL,
  is_head_office INTEGER NOT NULL DEFAULT 0,
  address_line1 TEXT,
  city          TEXT,
  state         TEXT,
  state_code    TEXT,
  pincode       TEXT,
  phone         TEXT,
  email         TEXT,
  manager_user_id TEXT,
  latitude      REAL,                   -- geofence centre for GPS attendance
  longitude     REAL,
  geofence_m    INTEGER NOT NULL DEFAULT 200,
  status        TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','inactive')),
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL,
  UNIQUE (tenant_id, code)
);
CREATE INDEX idx_branches_tenant ON branches(tenant_id);

-- --------------------------------------------------------------------------
-- Companies — the legal entities whose books are filed. A tenant may manage
-- many (multi-company add-on); a client user may be scoped to a subset.
-- --------------------------------------------------------------------------
CREATE TABLE companies (
  id              TEXT PRIMARY KEY,
  tenant_id       TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  branch_id       TEXT REFERENCES branches(id) ON DELETE SET NULL,
  name            TEXT NOT NULL,
  legal_name      TEXT,
  entity_type     TEXT NOT NULL DEFAULT 'private_limited'
                    CHECK (entity_type IN ('proprietorship','partnership','llp','private_limited','public_limited','trust','society','huf','other')),
  gstin           TEXT,
  pan             TEXT,
  tan             TEXT,
  cin             TEXT,
  registration_no TEXT,
  email           TEXT,
  phone           TEXT,
  website         TEXT,
  address_line1   TEXT,
  address_line2   TEXT,
  city            TEXT,
  state           TEXT,
  state_code      TEXT NOT NULL DEFAULT '33',
  pincode         TEXT,
  country         TEXT NOT NULL DEFAULT 'IN',
  financial_year_start TEXT NOT NULL DEFAULT '04-01',
  gst_registration_type TEXT NOT NULL DEFAULT 'regular'
                    CHECK (gst_registration_type IN ('regular','composition','casual','non_resident','sez','unregistered')),
  gst_filing_frequency TEXT NOT NULL DEFAULT 'monthly'
                    CHECK (gst_filing_frequency IN ('monthly','quarterly')),
  logo_key        TEXT,
  status          TEXT NOT NULL DEFAULT 'active'
                    CHECK (status IN ('active','trial','inactive','suspended','archived')),
  is_demo         INTEGER NOT NULL DEFAULT 0,
  created_at      TEXT NOT NULL,
  updated_at      TEXT NOT NULL,
  deleted_at      TEXT
);
CREATE INDEX idx_companies_tenant ON companies(tenant_id, status);
CREATE INDEX idx_companies_branch ON companies(branch_id);
CREATE INDEX idx_companies_gstin ON companies(gstin);

-- --------------------------------------------------------------------------
-- Users
-- --------------------------------------------------------------------------
CREATE TABLE users (
  id                    TEXT PRIMARY KEY,
  tenant_id             TEXT REFERENCES tenants(id) ON DELETE CASCADE,  -- NULL only for platform Super Admin
  email                 TEXT NOT NULL,
  password_hash         TEXT NOT NULL,          -- PBKDF2-SHA256, salted, iteration-tagged
  full_name             TEXT NOT NULL,
  phone                 TEXT,
  avatar_key            TEXT,
  job_title             TEXT,
  branch_id             TEXT REFERENCES branches(id) ON DELETE SET NULL,
  status                TEXT NOT NULL DEFAULT 'active'
                          CHECK (status IN ('active','invited','suspended','locked','deactivated')),
  email_verified_at     TEXT,
  phone_verified_at     TEXT,
  twofa_enabled         INTEGER NOT NULL DEFAULT 0,
  twofa_secret          TEXT,                   -- AES-GCM encrypted TOTP seed
  twofa_backup_codes    TEXT,                   -- JSON array of hashed single-use codes
  twofa_enrolled_at     TEXT,
  must_change_password  INTEGER NOT NULL DEFAULT 0,
  failed_login_count    INTEGER NOT NULL DEFAULT 0,
  locked_until          TEXT,
  last_login_at         TEXT,
  last_login_ip         TEXT,
  locale                TEXT NOT NULL DEFAULT 'en-IN',
  timezone              TEXT NOT NULL DEFAULT 'Asia/Kolkata',
  theme                 TEXT NOT NULL DEFAULT 'dark' CHECK (theme IN ('dark','light','system')),
  is_demo               INTEGER NOT NULL DEFAULT 0,
  created_at            TEXT NOT NULL,
  updated_at            TEXT NOT NULL,
  deleted_at            TEXT
);
-- Email is unique per tenant; the platform Super Admin (tenant_id NULL) is
-- covered by the second, partial index.
CREATE UNIQUE INDEX idx_users_tenant_email ON users(tenant_id, email) WHERE tenant_id IS NOT NULL;
CREATE UNIQUE INDEX idx_users_platform_email ON users(email) WHERE tenant_id IS NULL;
CREATE INDEX idx_users_status ON users(tenant_id, status);
CREATE INDEX idx_users_branch ON users(branch_id);

-- --------------------------------------------------------------------------
-- Roles & permissions — seven system roles, plus tenant-defined custom roles.
-- --------------------------------------------------------------------------
CREATE TABLE roles (
  id            TEXT PRIMARY KEY,
  tenant_id     TEXT REFERENCES tenants(id) ON DELETE CASCADE,  -- NULL = system role
  key           TEXT NOT NULL,          -- super_admin | admin | finance_manager | ...
  name          TEXT NOT NULL,
  description   TEXT,
  level         INTEGER NOT NULL DEFAULT 50,  -- 100 highest; used for "can manage" checks
  is_system     INTEGER NOT NULL DEFAULT 0,
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
);
CREATE UNIQUE INDEX idx_roles_system_key ON roles(key) WHERE tenant_id IS NULL;
CREATE UNIQUE INDEX idx_roles_tenant_key ON roles(tenant_id, key) WHERE tenant_id IS NOT NULL;

CREATE TABLE permissions (
  key           TEXT PRIMARY KEY,       -- e.g. documents.verify
  resource      TEXT NOT NULL,
  action        TEXT NOT NULL,
  name          TEXT NOT NULL,
  description   TEXT,
  category      TEXT NOT NULL DEFAULT 'general'
);

CREATE TABLE role_permissions (
  role_id       TEXT NOT NULL REFERENCES roles(id) ON DELETE CASCADE,
  permission_key TEXT NOT NULL REFERENCES permissions(key) ON DELETE CASCADE,
  granted       INTEGER NOT NULL DEFAULT 1,
  PRIMARY KEY (role_id, permission_key)
);

CREATE TABLE user_roles (
  user_id       TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  role_id       TEXT NOT NULL REFERENCES roles(id) ON DELETE CASCADE,
  assigned_by   TEXT,
  assigned_at   TEXT NOT NULL,
  PRIMARY KEY (user_id, role_id)
);
CREATE INDEX idx_user_roles_role ON user_roles(role_id);

-- Per-user permission overrides on top of the role grant (grant or revoke).
CREATE TABLE user_permissions (
  user_id        TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  permission_key TEXT NOT NULL REFERENCES permissions(key) ON DELETE CASCADE,
  granted        INTEGER NOT NULL,
  assigned_by    TEXT,
  assigned_at    TEXT NOT NULL,
  PRIMARY KEY (user_id, permission_key)
);

-- --------------------------------------------------------------------------
-- Company membership — narrows a user's data visibility inside their tenant.
-- A user with no rows here sees every company in the tenant (subject to RBAC);
-- a user with rows sees only those companies. Client users always have rows.
-- --------------------------------------------------------------------------
CREATE TABLE user_companies (
  user_id       TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  company_id    TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
  relationship  TEXT NOT NULL DEFAULT 'member'
                  CHECK (relationship IN ('owner','member','assigned','readonly')),
  is_default    INTEGER NOT NULL DEFAULT 0,
  created_at    TEXT NOT NULL,
  PRIMARY KEY (user_id, company_id)
);
CREATE INDEX idx_user_companies_company ON user_companies(company_id);

-- --------------------------------------------------------------------------
-- Sessions — server-side record for every issued token, so sessions can be
-- listed and revoked (Enterprise Security add-on).
-- --------------------------------------------------------------------------
CREATE TABLE sessions (
  id              TEXT PRIMARY KEY,
  user_id         TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  tenant_id       TEXT,
  token_hash      TEXT NOT NULL UNIQUE,   -- SHA-256 of the bearer token
  device_id       TEXT,
  ip              TEXT,
  user_agent      TEXT,
  active_company_id TEXT,
  twofa_satisfied INTEGER NOT NULL DEFAULT 0,
  step_up_at      TEXT,
  created_at      TEXT NOT NULL,
  last_seen_at    TEXT NOT NULL,
  expires_at      TEXT NOT NULL,
  revoked_at      TEXT,
  revoked_reason  TEXT
);
CREATE INDEX idx_sessions_user ON sessions(user_id, revoked_at);
CREATE INDEX idx_sessions_expiry ON sessions(expires_at);

-- Short-lived challenge issued after password success, before the 2FA code.
CREATE TABLE auth_challenges (
  id            TEXT PRIMARY KEY,
  user_id       TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  kind          TEXT NOT NULL CHECK (kind IN ('totp','email_otp','sms_otp','step_up')),
  code_hash     TEXT,
  attempts      INTEGER NOT NULL DEFAULT 0,
  ip            TEXT,
  user_agent    TEXT,
  device_id     TEXT,
  consumed_at   TEXT,
  created_at    TEXT NOT NULL,
  expires_at    TEXT NOT NULL
);
CREATE INDEX idx_auth_challenges_user ON auth_challenges(user_id);

CREATE TABLE password_resets (
  id            TEXT PRIMARY KEY,
  user_id       TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  token_hash    TEXT NOT NULL UNIQUE,
  ip            TEXT,
  used_at       TEXT,
  created_at    TEXT NOT NULL,
  expires_at    TEXT NOT NULL
);

-- --------------------------------------------------------------------------
-- Devices & login anomaly tracking (Enterprise Security add-on)
-- --------------------------------------------------------------------------
CREATE TABLE devices (
  id             TEXT PRIMARY KEY,
  user_id        TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  tenant_id      TEXT,
  fingerprint    TEXT NOT NULL,
  label          TEXT,
  platform       TEXT,
  browser        TEXT,
  last_ip        TEXT,
  trusted        INTEGER NOT NULL DEFAULT 0,
  blocked        INTEGER NOT NULL DEFAULT 0,
  first_seen_at  TEXT NOT NULL,
  last_seen_at   TEXT NOT NULL,
  UNIQUE (user_id, fingerprint)
);
CREATE INDEX idx_devices_tenant ON devices(tenant_id);

CREATE TABLE login_events (
  id            TEXT PRIMARY KEY,
  tenant_id     TEXT,
  user_id       TEXT,
  email         TEXT,
  result        TEXT NOT NULL
                  CHECK (result IN ('success','bad_password','unknown_user','locked','twofa_required','twofa_failed','ip_blocked','device_blocked','suspended')),
  ip            TEXT,
  user_agent    TEXT,
  device_id     TEXT,
  anomaly       TEXT,                   -- new_device | new_ip | impossible_travel
  created_at    TEXT NOT NULL
);
CREATE INDEX idx_login_events_user ON login_events(user_id, created_at);
CREATE INDEX idx_login_events_tenant ON login_events(tenant_id, created_at);

CREATE TABLE ip_allowlist (
  id            TEXT PRIMARY KEY,
  tenant_id     TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  cidr          TEXT NOT NULL,
  label         TEXT,
  created_by    TEXT,
  created_at    TEXT NOT NULL
);
CREATE INDEX idx_ip_allowlist_tenant ON ip_allowlist(tenant_id);

CREATE TABLE security_policies (
  tenant_id            TEXT PRIMARY KEY REFERENCES tenants(id) ON DELETE CASCADE,
  enforce_2fa          INTEGER NOT NULL DEFAULT 0,
  enforce_2fa_roles    TEXT,            -- JSON array of role keys; NULL = all
  ip_allowlist_enabled INTEGER NOT NULL DEFAULT 0,
  session_ttl_hours    INTEGER NOT NULL DEFAULT 12,
  idle_timeout_minutes INTEGER NOT NULL DEFAULT 60,
  password_min_length  INTEGER NOT NULL DEFAULT 10,
  password_require_mixed INTEGER NOT NULL DEFAULT 1,
  password_expiry_days INTEGER NOT NULL DEFAULT 0,
  max_failed_logins    INTEGER NOT NULL DEFAULT 5,
  lockout_minutes      INTEGER NOT NULL DEFAULT 15,
  device_approval      INTEGER NOT NULL DEFAULT 0,
  anomaly_alerts       INTEGER NOT NULL DEFAULT 1,
  step_up_for_sensitive INTEGER NOT NULL DEFAULT 0,
  updated_by           TEXT,
  updated_at           TEXT NOT NULL
);

-- ===== 0002_clients_and_documents.sql =====

-- =============================================================================
-- 0002 — Clients, document management, verification and the query workflow
-- =============================================================================

PRAGMA foreign_keys = ON;

-- --------------------------------------------------------------------------
-- Clients — the firm's customer. Always bound to exactly one company record
-- (the legal entity being filed for) so tax data never crosses entities.
-- --------------------------------------------------------------------------
CREATE TABLE clients (
  id                  TEXT PRIMARY KEY,
  tenant_id           TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  company_id          TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
  branch_id           TEXT REFERENCES branches(id) ON DELETE SET NULL,
  client_code         TEXT NOT NULL,
  display_name        TEXT NOT NULL,
  primary_contact_name  TEXT,
  primary_contact_email TEXT,
  primary_contact_phone TEXT,
  assigned_executive_id TEXT REFERENCES users(id) ON DELETE SET NULL,
  assigned_manager_id   TEXT REFERENCES users(id) ON DELETE SET NULL,
  onboarding_status   TEXT NOT NULL DEFAULT 'pending'
                        CHECK (onboarding_status IN ('pending','profile','documents','active')),
  status              TEXT NOT NULL DEFAULT 'active'
                        CHECK (status IN ('active','inactive','at_risk','churned','archived')),
  health_score        INTEGER,          -- 0-100, maintained by AI Business Insights
  source              TEXT,             -- manual | meta_ads | website_form | google_form | sheet | referral
  utm_json            TEXT,
  tags_json           TEXT,
  notes               TEXT,
  sla_hours           INTEGER NOT NULL DEFAULT 48,
  billing_day         INTEGER NOT NULL DEFAULT 1,
  is_demo             INTEGER NOT NULL DEFAULT 0,
  created_at          TEXT NOT NULL,
  updated_at          TEXT NOT NULL,
  deleted_at          TEXT,
  UNIQUE (tenant_id, client_code)
);
CREATE INDEX idx_clients_tenant ON clients(tenant_id, status);
CREATE INDEX idx_clients_company ON clients(company_id);
CREATE INDEX idx_clients_executive ON clients(assigned_executive_id);
CREATE INDEX idx_clients_branch ON clients(branch_id);

CREATE TABLE client_contacts (
  id            TEXT PRIMARY KEY,
  tenant_id     TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  client_id     TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  user_id       TEXT REFERENCES users(id) ON DELETE SET NULL,
  name          TEXT NOT NULL,
  email         TEXT,
  phone         TEXT,
  designation   TEXT,
  is_primary    INTEGER NOT NULL DEFAULT 0,
  whatsapp_opt_in INTEGER NOT NULL DEFAULT 0,
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
);
CREATE INDEX idx_client_contacts_client ON client_contacts(client_id);
CREATE INDEX idx_client_contacts_phone ON client_contacts(phone);

-- --------------------------------------------------------------------------
-- Document types — the 18+ categories named in the proposal. Seeded as system
-- rows; a tenant may add its own.
-- --------------------------------------------------------------------------
CREATE TABLE document_types (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT REFERENCES tenants(id) ON DELETE CASCADE,  -- NULL = system type
  key               TEXT NOT NULL,
  name              TEXT NOT NULL,
  category          TEXT NOT NULL
                      CHECK (category IN ('gst','sales','purchase','banking','expense','payment','tds','payroll','returns','tax','statutory','other')),
  description       TEXT,
  periodicity       TEXT NOT NULL DEFAULT 'monthly'
                      CHECK (periodicity IN ('monthly','quarterly','yearly','one_time','ad_hoc')),
  is_required       INTEGER NOT NULL DEFAULT 1,
  accepts_mime      TEXT,              -- JSON array; NULL = tenant default
  max_bytes         INTEGER,           -- NULL = tenant/plan default
  ocr_profile       TEXT,              -- gst_invoice | bank_statement | pan | aadhaar | none
  sort_order        INTEGER NOT NULL DEFAULT 100,
  is_active         INTEGER NOT NULL DEFAULT 1,
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL
);
CREATE UNIQUE INDEX idx_doctypes_system_key ON document_types(key) WHERE tenant_id IS NULL;
CREATE UNIQUE INDEX idx_doctypes_tenant_key ON document_types(tenant_id, key) WHERE tenant_id IS NOT NULL;

-- --------------------------------------------------------------------------
-- Filing periods — the unit of work: one client, one period, one filing cycle.
-- --------------------------------------------------------------------------
CREATE TABLE filing_periods (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  company_id        TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
  client_id         TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  period_type       TEXT NOT NULL CHECK (period_type IN ('monthly','quarterly','yearly')),
  period_key        TEXT NOT NULL,      -- 2026-08 | 2026-Q1 | 2026-27
  period_start      TEXT NOT NULL,
  period_end        TEXT NOT NULL,
  due_date          TEXT,
  status            TEXT NOT NULL DEFAULT 'collecting'
                      CHECK (status IN ('collecting','under_review','query_raised','awaiting_client','verified','calculated','pending_approval','approved','client_review','signed_off','paid','filed','archived','rejected')),
  documents_expected INTEGER NOT NULL DEFAULT 0,
  documents_received INTEGER NOT NULL DEFAULT 0,
  documents_verified INTEGER NOT NULL DEFAULT 0,
  locked_at         TEXT,
  archived_at       TEXT,
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL,
  UNIQUE (client_id, period_type, period_key)
);
CREATE INDEX idx_periods_tenant ON filing_periods(tenant_id, status);
CREATE INDEX idx_periods_client ON filing_periods(client_id, period_key);
CREATE INDEX idx_periods_due ON filing_periods(tenant_id, due_date);

-- --------------------------------------------------------------------------
-- Documents — the current head of a versioned document.
-- --------------------------------------------------------------------------
CREATE TABLE documents (
  id                  TEXT PRIMARY KEY,
  tenant_id           TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  company_id          TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
  client_id           TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  filing_period_id    TEXT REFERENCES filing_periods(id) ON DELETE SET NULL,
  document_type_id    TEXT NOT NULL REFERENCES document_types(id),
  title               TEXT NOT NULL,
  description         TEXT,
  period_key          TEXT,
  current_version_id  TEXT,
  version_count       INTEGER NOT NULL DEFAULT 1,
  status              TEXT NOT NULL DEFAULT 'submitted'
                        CHECK (status IN ('draft','submitted','under_review','query_raised','awaiting_client','verified','rejected','approved','archived')),
  priority            TEXT NOT NULL DEFAULT 'normal'
                        CHECK (priority IN ('low','normal','high','urgent')),
  assigned_to         TEXT REFERENCES users(id) ON DELETE SET NULL,
  verified_by         TEXT REFERENCES users(id) ON DELETE SET NULL,
  verified_at         TEXT,
  rejected_reason     TEXT,
  is_locked           INTEGER NOT NULL DEFAULT 0,
  locked_by           TEXT,
  locked_at           TEXT,
  source              TEXT NOT NULL DEFAULT 'portal'
                        CHECK (source IN ('portal','mobile','whatsapp','email','drive','dropbox','onedrive','api','zip','gps_visit')),
  from_zip_batch_id   TEXT,
  ocr_status          TEXT NOT NULL DEFAULT 'none'
                        CHECK (ocr_status IN ('none','queued','processing','done','failed','skipped')),
  ai_precheck_status  TEXT NOT NULL DEFAULT 'none'
                        CHECK (ai_precheck_status IN ('none','queued','processing','clean','flagged','failed','skipped')),
  ai_confidence       REAL,
  sla_due_at          TEXT,
  submitted_at        TEXT,
  created_by          TEXT,
  created_at          TEXT NOT NULL,
  updated_at          TEXT NOT NULL,
  deleted_at          TEXT
);
CREATE INDEX idx_documents_tenant_status ON documents(tenant_id, status);
CREATE INDEX idx_documents_client ON documents(client_id, status);
CREATE INDEX idx_documents_period ON documents(filing_period_id);
CREATE INDEX idx_documents_assigned ON documents(assigned_to, status);
CREATE INDEX idx_documents_type ON documents(document_type_id);
CREATE INDEX idx_documents_company ON documents(company_id);

-- --------------------------------------------------------------------------
-- Document versions — immutable. A replace writes a new row; nothing is
-- overwritten, so the audit trail survives every correction.
-- --------------------------------------------------------------------------
CREATE TABLE document_versions (
  id              TEXT PRIMARY KEY,
  tenant_id       TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  document_id     TEXT NOT NULL REFERENCES documents(id) ON DELETE CASCADE,
  version_no      INTEGER NOT NULL,
  storage_key     TEXT NOT NULL,        -- R2 object key, never a public URL
  file_name       TEXT NOT NULL,
  mime_type       TEXT NOT NULL,
  size_bytes      INTEGER NOT NULL,
  checksum_sha256 TEXT,
  page_count      INTEGER,
  uploaded_by     TEXT REFERENCES users(id) ON DELETE SET NULL,
  upload_note     TEXT,
  replaces_version_id TEXT,
  is_current      INTEGER NOT NULL DEFAULT 1,
  scan_status     TEXT NOT NULL DEFAULT 'pending'
                    CHECK (scan_status IN ('pending','clean','infected','skipped','failed')),
  created_at      TEXT NOT NULL,
  UNIQUE (document_id, version_no)
);
CREATE INDEX idx_docversions_document ON document_versions(document_id, version_no);
CREATE INDEX idx_docversions_tenant ON document_versions(tenant_id);

-- ZIP batches — one row per bulk upload, so a month's drop is traceable.
CREATE TABLE upload_batches (
  id              TEXT PRIMARY KEY,
  tenant_id       TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  client_id       TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  filing_period_id TEXT REFERENCES filing_periods(id) ON DELETE SET NULL,
  kind            TEXT NOT NULL DEFAULT 'zip' CHECK (kind IN ('zip','multi','sync')),
  archive_name    TEXT,
  archive_key     TEXT,
  total_entries   INTEGER NOT NULL DEFAULT 0,
  extracted_count INTEGER NOT NULL DEFAULT 0,
  skipped_count   INTEGER NOT NULL DEFAULT 0,
  failed_count    INTEGER NOT NULL DEFAULT 0,
  status          TEXT NOT NULL DEFAULT 'processing'
                    CHECK (status IN ('processing','completed','partial','failed')),
  report_json     TEXT,
  created_by      TEXT,
  created_at      TEXT NOT NULL,
  completed_at    TEXT
);
CREATE INDEX idx_batches_client ON upload_batches(client_id);

-- --------------------------------------------------------------------------
-- Comments — internal notes and client-visible remarks on a document.
-- --------------------------------------------------------------------------
CREATE TABLE document_comments (
  id            TEXT PRIMARY KEY,
  tenant_id     TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  document_id   TEXT NOT NULL REFERENCES documents(id) ON DELETE CASCADE,
  version_id    TEXT REFERENCES document_versions(id) ON DELETE SET NULL,
  author_id     TEXT REFERENCES users(id) ON DELETE SET NULL,
  body          TEXT NOT NULL,
  visibility    TEXT NOT NULL DEFAULT 'shared'
                  CHECK (visibility IN ('shared','internal')),
  anchor_json   TEXT,                   -- optional page/region for inline notes
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL,
  deleted_at    TEXT
);
CREATE INDEX idx_doccomments_document ON document_comments(document_id, created_at);

-- --------------------------------------------------------------------------
-- Verification records — one immutable row per executive decision.
-- --------------------------------------------------------------------------
CREATE TABLE verification_records (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  document_id       TEXT NOT NULL REFERENCES documents(id) ON DELETE CASCADE,
  version_id        TEXT REFERENCES document_versions(id) ON DELETE SET NULL,
  verifier_id       TEXT REFERENCES users(id) ON DELETE SET NULL,
  decision          TEXT NOT NULL
                      CHECK (decision IN ('approved','rejected','query_raised','changes_requested','reopened','locked','unlocked')),
  reason_code       TEXT,
  notes             TEXT,
  checklist_json    TEXT,
  time_spent_seconds INTEGER,
  sla_met           INTEGER,
  created_at        TEXT NOT NULL
);
CREATE INDEX idx_verifications_document ON verification_records(document_id, created_at);
CREATE INDEX idx_verifications_verifier ON verification_records(verifier_id, created_at);
CREATE INDEX idx_verifications_tenant ON verification_records(tenant_id, created_at);

-- --------------------------------------------------------------------------
-- Queries — the executive↔client correction loop.
-- --------------------------------------------------------------------------
CREATE TABLE queries (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  company_id        TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
  client_id         TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  document_id       TEXT REFERENCES documents(id) ON DELETE SET NULL,
  filing_period_id  TEXT REFERENCES filing_periods(id) ON DELETE SET NULL,
  reference_no      TEXT NOT NULL,
  subject           TEXT NOT NULL,
  body              TEXT NOT NULL,
  category          TEXT NOT NULL DEFAULT 'document'
                      CHECK (category IN ('document','data','clarification','missing','mismatch','other')),
  priority          TEXT NOT NULL DEFAULT 'normal'
                      CHECK (priority IN ('low','normal','high','urgent')),
  status            TEXT NOT NULL DEFAULT 'open'
                      CHECK (status IN ('open','awaiting_client','client_responded','under_review','resolved','cancelled')),
  raised_by         TEXT REFERENCES users(id) ON DELETE SET NULL,
  assigned_to       TEXT REFERENCES users(id) ON DELETE SET NULL,
  resolved_by       TEXT REFERENCES users(id) ON DELETE SET NULL,
  resolved_at       TEXT,
  resolution_note   TEXT,
  due_at            TEXT,
  first_response_at TEXT,
  reply_count       INTEGER NOT NULL DEFAULT 0,
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL,
  UNIQUE (tenant_id, reference_no)
);
CREATE INDEX idx_queries_client ON queries(client_id, status);
CREATE INDEX idx_queries_tenant ON queries(tenant_id, status);
CREATE INDEX idx_queries_document ON queries(document_id);
CREATE INDEX idx_queries_assigned ON queries(assigned_to, status);

CREATE TABLE query_replies (
  id              TEXT PRIMARY KEY,
  tenant_id       TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  query_id        TEXT NOT NULL REFERENCES queries(id) ON DELETE CASCADE,
  author_id       TEXT REFERENCES users(id) ON DELETE SET NULL,
  author_role     TEXT,
  body            TEXT NOT NULL,
  visibility      TEXT NOT NULL DEFAULT 'shared'
                    CHECK (visibility IN ('shared','internal')),
  attachments_json TEXT,                -- [{documentId, versionId, fileName}]
  channel         TEXT NOT NULL DEFAULT 'portal'
                    CHECK (channel IN ('portal','email','whatsapp','sms','mobile','voice_note')),
  created_at      TEXT NOT NULL
);
CREATE INDEX idx_queryreplies_query ON query_replies(query_id, created_at);

-- Document checklist — what a client still owes for a period.
CREATE TABLE checklist_items (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  filing_period_id  TEXT NOT NULL REFERENCES filing_periods(id) ON DELETE CASCADE,
  document_type_id  TEXT NOT NULL REFERENCES document_types(id),
  document_id       TEXT REFERENCES documents(id) ON DELETE SET NULL,
  label             TEXT NOT NULL,
  is_required       INTEGER NOT NULL DEFAULT 1,
  status            TEXT NOT NULL DEFAULT 'pending'
                      CHECK (status IN ('pending','submitted','under_review','query_raised','verified','rejected','waived')),
  waived_reason     TEXT,
  sort_order        INTEGER NOT NULL DEFAULT 100,
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL
);
CREATE INDEX idx_checklist_period ON checklist_items(filing_period_id);

-- ===== 0003_tax_reports_workflow.sql =====

-- =============================================================================
-- 0003 — Tax engine, reports, approvals, tasks and the activity trail
-- =============================================================================

PRAGMA foreign_keys = ON;

-- --------------------------------------------------------------------------
-- Tax rules — rates and thresholds live in data, not in code, so a rate change
-- is a row insert rather than a deploy. Every rule is version-dated.
-- --------------------------------------------------------------------------
CREATE TABLE tax_rules (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT REFERENCES tenants(id) ON DELETE CASCADE,  -- NULL = platform default
  regime            TEXT NOT NULL CHECK (regime IN ('gst','tds','tcs','cess')),
  code              TEXT NOT NULL,          -- GST_5 | GST_18 | TDS_194C_IND ...
  name              TEXT NOT NULL,
  description       TEXT,
  hsn_sac           TEXT,
  section_code      TEXT,                   -- TDS section, e.g. 194C
  rate_pct          REAL NOT NULL DEFAULT 0,
  cgst_pct          REAL NOT NULL DEFAULT 0,
  sgst_pct          REAL NOT NULL DEFAULT 0,
  igst_pct          REAL NOT NULL DEFAULT 0,
  cess_pct          REAL NOT NULL DEFAULT 0,
  threshold_paise   INTEGER NOT NULL DEFAULT 0,
  payee_type        TEXT,                   -- individual | company | any
  effective_from    TEXT NOT NULL,
  effective_to      TEXT,
  is_verified       INTEGER NOT NULL DEFAULT 1,  -- 0 = AI-suggested, awaiting sign-off
  source_note       TEXT,
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL
);
CREATE INDEX idx_taxrules_lookup ON tax_rules(regime, code, effective_from);
CREATE INDEX idx_taxrules_tenant ON tax_rules(tenant_id, regime);

-- --------------------------------------------------------------------------
-- Tax computations — one header per client/period/regime, recomputable.
-- --------------------------------------------------------------------------
CREATE TABLE tax_computations (
  id                    TEXT PRIMARY KEY,
  tenant_id             TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  company_id            TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
  client_id             TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  filing_period_id      TEXT NOT NULL REFERENCES filing_periods(id) ON DELETE CASCADE,
  regime                TEXT NOT NULL CHECK (regime IN ('gst','tds')),
  period_type           TEXT NOT NULL CHECK (period_type IN ('monthly','quarterly','yearly')),
  period_key            TEXT NOT NULL,
  -- GST: outward
  taxable_value_paise   INTEGER NOT NULL DEFAULT 0,
  cgst_paise            INTEGER NOT NULL DEFAULT 0,
  sgst_paise            INTEGER NOT NULL DEFAULT 0,
  igst_paise            INTEGER NOT NULL DEFAULT 0,
  cess_paise            INTEGER NOT NULL DEFAULT 0,
  total_tax_paise       INTEGER NOT NULL DEFAULT 0,
  -- GST: inward / input credit
  itc_taxable_paise     INTEGER NOT NULL DEFAULT 0,
  itc_cgst_paise        INTEGER NOT NULL DEFAULT 0,
  itc_sgst_paise        INTEGER NOT NULL DEFAULT 0,
  itc_igst_paise        INTEGER NOT NULL DEFAULT 0,
  itc_cess_paise        INTEGER NOT NULL DEFAULT 0,
  itc_total_paise       INTEGER NOT NULL DEFAULT 0,
  net_payable_paise     INTEGER NOT NULL DEFAULT 0,
  -- TDS
  tds_base_paise        INTEGER NOT NULL DEFAULT 0,
  tds_deducted_paise    INTEGER NOT NULL DEFAULT 0,
  tds_deposited_paise   INTEGER NOT NULL DEFAULT 0,
  -- provenance
  status                TEXT NOT NULL DEFAULT 'draft'
                          CHECK (status IN ('draft','computed','stale','superseded','final')),
  source_document_count INTEGER NOT NULL DEFAULT 0,
  line_count            INTEGER NOT NULL DEFAULT 0,
  warnings_json         TEXT,
  computed_by           TEXT REFERENCES users(id) ON DELETE SET NULL,
  computed_at           TEXT,
  engine_version        TEXT NOT NULL DEFAULT '1.0.0',
  created_at            TEXT NOT NULL,
  updated_at            TEXT NOT NULL
);
CREATE INDEX idx_taxcomp_period ON tax_computations(filing_period_id, regime);
CREATE INDEX idx_taxcomp_client ON tax_computations(client_id, period_key);
CREATE INDEX idx_taxcomp_tenant ON tax_computations(tenant_id, regime, period_key);

-- GST line items — every figure the summary is built from stays inspectable.
CREATE TABLE gst_records (
  id                  TEXT PRIMARY KEY,
  tenant_id           TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  computation_id      TEXT NOT NULL REFERENCES tax_computations(id) ON DELETE CASCADE,
  client_id           TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  document_id         TEXT REFERENCES documents(id) ON DELETE SET NULL,
  direction           TEXT NOT NULL CHECK (direction IN ('outward','inward')),
  supply_type         TEXT NOT NULL DEFAULT 'intra'
                        CHECK (supply_type IN ('intra','inter','export','exempt','nil','non_gst','rcm')),
  invoice_no          TEXT,
  invoice_date        TEXT,
  counterparty_name   TEXT,
  counterparty_gstin  TEXT,
  place_of_supply     TEXT,
  hsn_sac             TEXT,
  description         TEXT,
  quantity            REAL,
  taxable_value_paise INTEGER NOT NULL DEFAULT 0,
  rate_pct            REAL NOT NULL DEFAULT 0,
  cgst_paise          INTEGER NOT NULL DEFAULT 0,
  sgst_paise          INTEGER NOT NULL DEFAULT 0,
  igst_paise          INTEGER NOT NULL DEFAULT 0,
  cess_paise          INTEGER NOT NULL DEFAULT 0,
  total_paise         INTEGER NOT NULL DEFAULT 0,
  itc_eligible        INTEGER NOT NULL DEFAULT 1,
  source              TEXT NOT NULL DEFAULT 'manual'
                        CHECK (source IN ('manual','ocr','import','api','sheet')),
  ocr_confidence      REAL,
  created_at          TEXT NOT NULL,
  updated_at          TEXT NOT NULL
);
CREATE INDEX idx_gstrecords_computation ON gst_records(computation_id, direction);
CREATE INDEX idx_gstrecords_client ON gst_records(client_id);
CREATE INDEX idx_gstrecords_document ON gst_records(document_id);

CREATE TABLE tds_records (
  id                  TEXT PRIMARY KEY,
  tenant_id           TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  computation_id      TEXT NOT NULL REFERENCES tax_computations(id) ON DELETE CASCADE,
  client_id           TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  document_id         TEXT REFERENCES documents(id) ON DELETE SET NULL,
  section_code        TEXT NOT NULL,
  deductee_name       TEXT,
  deductee_pan        TEXT,
  payee_type          TEXT NOT NULL DEFAULT 'company'
                        CHECK (payee_type IN ('individual','huf','company','firm','other')),
  payment_date        TEXT,
  amount_paise        INTEGER NOT NULL DEFAULT 0,
  rate_pct            REAL NOT NULL DEFAULT 0,
  tds_paise           INTEGER NOT NULL DEFAULT 0,
  deposited_paise     INTEGER NOT NULL DEFAULT 0,
  challan_no          TEXT,
  deposited_on        TEXT,
  lower_deduction_cert TEXT,
  source              TEXT NOT NULL DEFAULT 'manual'
                        CHECK (source IN ('manual','ocr','import','api','sheet')),
  created_at          TEXT NOT NULL,
  updated_at          TEXT NOT NULL
);
CREATE INDEX idx_tdsrecords_computation ON tds_records(computation_id);
CREATE INDEX idx_tdsrecords_client ON tds_records(client_id);

-- --------------------------------------------------------------------------
-- Reports — the artefact a manager approves and a client signs off.
-- --------------------------------------------------------------------------
CREATE TABLE reports (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  company_id        TEXT REFERENCES companies(id) ON DELETE CASCADE,
  client_id         TEXT REFERENCES clients(id) ON DELETE CASCADE,
  filing_period_id  TEXT REFERENCES filing_periods(id) ON DELETE SET NULL,
  computation_id    TEXT REFERENCES tax_computations(id) ON DELETE SET NULL,
  reference_no      TEXT NOT NULL,
  type              TEXT NOT NULL
                      CHECK (type IN ('gst_summary','monthly_tax','quarterly','yearly','tds_summary','revenue','expenses','outstanding_payments','client_report','audit_report','team_performance','call_report','analytics','custom')),
  title             TEXT NOT NULL,
  period_type       TEXT,
  period_key        TEXT,
  period_start      TEXT,
  period_end        TEXT,
  status            TEXT NOT NULL DEFAULT 'draft'
                      CHECK (status IN ('draft','pending_approval','approved','rejected','client_review','signed_off','published','archived')),
  totals_json       TEXT,
  payload_json      TEXT,
  filters_json      TEXT,
  narrative         TEXT,
  ai_generated      INTEGER NOT NULL DEFAULT 0,
  ai_reviewed_by    TEXT,
  generated_by      TEXT REFERENCES users(id) ON DELETE SET NULL,
  generated_at      TEXT,
  submitted_at      TEXT,
  approved_by       TEXT REFERENCES users(id) ON DELETE SET NULL,
  approved_at       TEXT,
  rejected_reason   TEXT,
  client_signed_off_by TEXT REFERENCES users(id) ON DELETE SET NULL,
  client_signed_off_at TEXT,
  pdf_key           TEXT,
  csv_key           TEXT,
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL,
  UNIQUE (tenant_id, reference_no)
);
CREATE INDEX idx_reports_tenant_status ON reports(tenant_id, status);
CREATE INDEX idx_reports_client ON reports(client_id, period_key);
CREATE INDEX idx_reports_period ON reports(filing_period_id);
CREATE INDEX idx_reports_type ON reports(tenant_id, type);

CREATE TABLE report_items (
  id            TEXT PRIMARY KEY,
  tenant_id     TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  report_id     TEXT NOT NULL REFERENCES reports(id) ON DELETE CASCADE,
  section       TEXT NOT NULL,
  label         TEXT NOT NULL,
  value_paise   INTEGER,
  value_text    TEXT,
  value_number  REAL,
  unit          TEXT,
  sort_order    INTEGER NOT NULL DEFAULT 100,
  meta_json     TEXT
);
CREATE INDEX idx_reportitems_report ON report_items(report_id, sort_order);

-- --------------------------------------------------------------------------
-- Approvals — a generic chain usable by reports, payments, users, add-ons.
-- --------------------------------------------------------------------------
CREATE TABLE approvals (
  id              TEXT PRIMARY KEY,
  tenant_id       TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  entity_type     TEXT NOT NULL,        -- report | tax_computation | payout | user | addon
  entity_id       TEXT NOT NULL,
  stage           TEXT NOT NULL DEFAULT 'manager'
                    CHECK (stage IN ('executive','manager','admin','client')),
  status          TEXT NOT NULL DEFAULT 'pending'
                    CHECK (status IN ('pending','approved','rejected','withdrawn','skipped')),
  requested_by    TEXT REFERENCES users(id) ON DELETE SET NULL,
  requested_at    TEXT NOT NULL,
  assignee_id     TEXT REFERENCES users(id) ON DELETE SET NULL,
  decided_by      TEXT REFERENCES users(id) ON DELETE SET NULL,
  decided_at      TEXT,
  comment         TEXT,
  due_at          TEXT,
  sequence        INTEGER NOT NULL DEFAULT 1,
  created_at      TEXT NOT NULL
);
CREATE INDEX idx_approvals_entity ON approvals(entity_type, entity_id);
CREATE INDEX idx_approvals_assignee ON approvals(assignee_id, status);
CREATE INDEX idx_approvals_tenant ON approvals(tenant_id, status);

-- --------------------------------------------------------------------------
-- Tasks — internal work items, including those auto-created after a call.
-- --------------------------------------------------------------------------
CREATE TABLE tasks (
  id              TEXT PRIMARY KEY,
  tenant_id       TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  company_id      TEXT REFERENCES companies(id) ON DELETE CASCADE,
  client_id       TEXT REFERENCES clients(id) ON DELETE CASCADE,
  filing_period_id TEXT REFERENCES filing_periods(id) ON DELETE SET NULL,
  title           TEXT NOT NULL,
  description     TEXT,
  type            TEXT NOT NULL DEFAULT 'general'
                    CHECK (type IN ('general','verification','follow_up','call_follow_up','collection','filing','reconciliation','onboarding','support')),
  status          TEXT NOT NULL DEFAULT 'todo'
                    CHECK (status IN ('todo','in_progress','blocked','review','done','cancelled')),
  priority        TEXT NOT NULL DEFAULT 'normal'
                    CHECK (priority IN ('low','normal','high','urgent')),
  assigned_to     TEXT REFERENCES users(id) ON DELETE SET NULL,
  created_by      TEXT REFERENCES users(id) ON DELETE SET NULL,
  due_at          TEXT,
  reminder_at     TEXT,
  completed_at    TEXT,
  source_type     TEXT,                 -- call | query | document | report | manual
  source_id       TEXT,
  created_at      TEXT NOT NULL,
  updated_at      TEXT NOT NULL
);
CREATE INDEX idx_tasks_assignee ON tasks(assigned_to, status);
CREATE INDEX idx_tasks_tenant ON tasks(tenant_id, status);
CREATE INDEX idx_tasks_client ON tasks(client_id);
CREATE INDEX idx_tasks_due ON tasks(tenant_id, due_at);

-- --------------------------------------------------------------------------
-- Activities — the human-readable client timeline (distinct from audit_logs,
-- which is the tamper-evident compliance record).
-- --------------------------------------------------------------------------
CREATE TABLE activities (
  id            TEXT PRIMARY KEY,
  tenant_id     TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  company_id    TEXT,
  client_id     TEXT,
  actor_id      TEXT,
  actor_name    TEXT,
  actor_role    TEXT,
  verb          TEXT NOT NULL,          -- uploaded | verified | raised_query | called ...
  entity_type   TEXT NOT NULL,
  entity_id     TEXT,
  summary       TEXT NOT NULL,
  detail_json   TEXT,
  visibility    TEXT NOT NULL DEFAULT 'internal'
                  CHECK (visibility IN ('internal','client','public')),
  icon          TEXT,
  created_at    TEXT NOT NULL
);
CREATE INDEX idx_activities_client ON activities(client_id, created_at);
CREATE INDEX idx_activities_tenant ON activities(tenant_id, created_at);
CREATE INDEX idx_activities_entity ON activities(entity_type, entity_id);

-- ===== 0004_billing_and_addons.sql =====

-- =============================================================================
-- 0004 — Plans, subscriptions, add-on marketplace, invoices and payments
-- =============================================================================

PRAGMA foreign_keys = ON;

-- --------------------------------------------------------------------------
-- Plans — Basic / Standard / Pro exactly as priced in the proposal.
-- --------------------------------------------------------------------------
CREATE TABLE plans (
  id                  TEXT PRIMARY KEY,
  key                 TEXT NOT NULL UNIQUE,   -- basic | standard | pro | enterprise
  name                TEXT NOT NULL,
  tagline             TEXT,
  monthly_price_paise INTEGER NOT NULL DEFAULT 0,
  yearly_price_paise  INTEGER NOT NULL DEFAULT 0,
  currency            TEXT NOT NULL DEFAULT 'INR',
  -- Limits. -1 means unlimited.
  max_users           INTEGER NOT NULL DEFAULT 1,
  max_companies       INTEGER NOT NULL DEFAULT 1,
  storage_gb          INTEGER NOT NULL DEFAULT 5,
  max_uploads_month   INTEGER NOT NULL DEFAULT 50,
  support_level       TEXT NOT NULL DEFAULT 'email'
                        CHECK (support_level IN ('email','email_chat','priority')),
  is_public           INTEGER NOT NULL DEFAULT 1,
  is_popular          INTEGER NOT NULL DEFAULT 0,
  sort_order          INTEGER NOT NULL DEFAULT 100,
  trial_days          INTEGER NOT NULL DEFAULT 0,
  created_at          TEXT NOT NULL,
  updated_at          TEXT NOT NULL
);

-- Boolean/valued capabilities a plan unlocks. The gating layer reads this.
CREATE TABLE plan_features (
  plan_id       TEXT NOT NULL REFERENCES plans(id) ON DELETE CASCADE,
  feature_key   TEXT NOT NULL,          -- gst_reports | ocr_ai | api_access | white_label ...
  enabled       INTEGER NOT NULL DEFAULT 1,
  value         TEXT,                   -- optional numeric/text limit
  label         TEXT,
  sort_order    INTEGER NOT NULL DEFAULT 100,
  PRIMARY KEY (plan_id, feature_key)
);

CREATE TABLE subscriptions (
  id                  TEXT PRIMARY KEY,
  tenant_id           TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  plan_id             TEXT NOT NULL REFERENCES plans(id),
  status              TEXT NOT NULL DEFAULT 'active'
                        CHECK (status IN ('trialing','active','past_due','paused','cancelled','expired')),
  billing_cycle       TEXT NOT NULL DEFAULT 'monthly'
                        CHECK (billing_cycle IN ('monthly','yearly')),
  seats               INTEGER NOT NULL DEFAULT 1,
  unit_price_paise    INTEGER NOT NULL DEFAULT 0,
  current_period_start TEXT NOT NULL,
  current_period_end   TEXT NOT NULL,
  trial_ends_at       TEXT,
  auto_renew          INTEGER NOT NULL DEFAULT 1,
  cancel_at_period_end INTEGER NOT NULL DEFAULT 0,
  cancelled_at        TEXT,
  cancellation_reason TEXT,
  gateway             TEXT,
  gateway_subscription_id TEXT,
  created_at          TEXT NOT NULL,
  updated_at          TEXT NOT NULL
);
CREATE INDEX idx_subscriptions_tenant ON subscriptions(tenant_id, status);
CREATE INDEX idx_subscriptions_renewal ON subscriptions(current_period_end, auto_renew);

-- Rolling usage counters, reset per billing period; the gate reads these.
CREATE TABLE subscription_usage (
  id            TEXT PRIMARY KEY,
  tenant_id     TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  metric        TEXT NOT NULL,          -- users | companies | storage_bytes | uploads | api_calls | calls | sms | whatsapp
  period_key    TEXT NOT NULL,          -- YYYY-MM, or 'current' for absolute gauges
  value         INTEGER NOT NULL DEFAULT 0,
  updated_at    TEXT NOT NULL,
  UNIQUE (tenant_id, metric, period_key)
);

-- --------------------------------------------------------------------------
-- Add-on marketplace — the 30 modules from the addendum. Catalogue rows are
-- platform-owned; activation rows are per tenant.
-- --------------------------------------------------------------------------
CREATE TABLE add_ons (
  id                  TEXT PRIMARY KEY,
  key                 TEXT NOT NULL UNIQUE,
  number              INTEGER NOT NULL,       -- 1..30, marketplace ordering
  name                TEXT NOT NULL,
  category            TEXT NOT NULL,
  category_no         INTEGER NOT NULL,
  description         TEXT NOT NULL,
  business_benefit    TEXT,
  workflow            TEXT,
  features_json       TEXT NOT NULL,          -- string[]
  ui_screens_json     TEXT,                   -- string[]
  user_roles_json     TEXT,                   -- role keys that can use it
  apis_required_json  TEXT,                   -- vendor APIs it needs
  provider_keys_json  TEXT,                   -- env var names required to connect
  best_plan           TEXT NOT NULL,          -- "Pro / Enterprise"
  best_plan_keys_json TEXT,
  monthly_price_paise INTEGER NOT NULL,
  setup_fee_paise     INTEGER NOT NULL,
  feature_keys_json   TEXT,                   -- capabilities the add-on unlocks
  icon                TEXT,
  accent              TEXT,
  requires_credentials INTEGER NOT NULL DEFAULT 1,
  is_available        INTEGER NOT NULL DEFAULT 1,
  created_at          TEXT NOT NULL,
  updated_at          TEXT NOT NULL
);
CREATE INDEX idx_addons_category ON add_ons(category_no, number);

CREATE TABLE add_on_subscriptions (
  id                  TEXT PRIMARY KEY,
  tenant_id           TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  add_on_id           TEXT NOT NULL REFERENCES add_ons(id) ON DELETE CASCADE,
  status              TEXT NOT NULL DEFAULT 'active'
                        CHECK (status IN ('active','trialing','suspended','cancelled','pending_payment')),
  activated_at        TEXT NOT NULL,
  activated_by        TEXT REFERENCES users(id) ON DELETE SET NULL,
  deactivated_at      TEXT,
  deactivated_by      TEXT,
  billing_cycle       TEXT NOT NULL DEFAULT 'monthly'
                        CHECK (billing_cycle IN ('monthly','yearly')),
  monthly_price_paise INTEGER NOT NULL,
  setup_fee_paise     INTEGER NOT NULL DEFAULT 0,
  setup_fee_charged   INTEGER NOT NULL DEFAULT 0,
  current_period_start TEXT,
  current_period_end   TEXT,
  config_json         TEXT,                   -- module configuration (non-secret)
  created_at          TEXT NOT NULL,
  updated_at          TEXT NOT NULL,
  UNIQUE (tenant_id, add_on_id)
);
CREATE INDEX idx_addonsubs_tenant ON add_on_subscriptions(tenant_id, status);

-- Per-add-on usage, for metered modules (SMS sent, OCR pages, call minutes).
CREATE TABLE add_on_usage (
  id            TEXT PRIMARY KEY,
  tenant_id     TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  add_on_id     TEXT NOT NULL REFERENCES add_ons(id) ON DELETE CASCADE,
  metric        TEXT NOT NULL,
  period_key    TEXT NOT NULL,
  value         INTEGER NOT NULL DEFAULT 0,
  updated_at    TEXT NOT NULL,
  UNIQUE (tenant_id, add_on_id, metric, period_key)
);

-- --------------------------------------------------------------------------
-- Invoices — both platform→tenant (subscription) and tenant→client (service).
-- --------------------------------------------------------------------------
CREATE TABLE invoices (
  id                  TEXT PRIMARY KEY,
  tenant_id           TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  client_id           TEXT REFERENCES clients(id) ON DELETE SET NULL,
  company_id          TEXT REFERENCES companies(id) ON DELETE SET NULL,
  subscription_id     TEXT REFERENCES subscriptions(id) ON DELETE SET NULL,
  filing_period_id    TEXT REFERENCES filing_periods(id) ON DELETE SET NULL,
  invoice_no          TEXT NOT NULL,
  direction           TEXT NOT NULL DEFAULT 'platform_to_tenant'
                        CHECK (direction IN ('platform_to_tenant','tenant_to_client')),
  kind                TEXT NOT NULL DEFAULT 'subscription'
                        CHECK (kind IN ('subscription','addon','setup','service','adjustment','credit_note')),
  status              TEXT NOT NULL DEFAULT 'draft'
                        CHECK (status IN ('draft','issued','sent','partially_paid','paid','overdue','void','refunded')),
  currency            TEXT NOT NULL DEFAULT 'INR',
  subtotal_paise      INTEGER NOT NULL DEFAULT 0,
  discount_paise      INTEGER NOT NULL DEFAULT 0,
  tax_paise           INTEGER NOT NULL DEFAULT 0,
  cgst_paise          INTEGER NOT NULL DEFAULT 0,
  sgst_paise          INTEGER NOT NULL DEFAULT 0,
  igst_paise          INTEGER NOT NULL DEFAULT 0,
  total_paise         INTEGER NOT NULL DEFAULT 0,
  amount_paid_paise   INTEGER NOT NULL DEFAULT 0,
  amount_due_paise    INTEGER NOT NULL DEFAULT 0,
  issue_date          TEXT NOT NULL,
  due_date            TEXT NOT NULL,
  paid_at             TEXT,
  notes               TEXT,
  terms               TEXT,
  billing_name        TEXT,
  billing_email       TEXT,
  billing_gstin       TEXT,
  billing_address     TEXT,
  place_of_supply     TEXT,
  pdf_key             TEXT,
  reminder_count      INTEGER NOT NULL DEFAULT 0,
  last_reminder_at    TEXT,
  created_by          TEXT,
  created_at          TEXT NOT NULL,
  updated_at          TEXT NOT NULL,
  UNIQUE (tenant_id, invoice_no)
);
CREATE INDEX idx_invoices_tenant_status ON invoices(tenant_id, status);
CREATE INDEX idx_invoices_client ON invoices(client_id, status);
CREATE INDEX idx_invoices_due ON invoices(status, due_date);

CREATE TABLE invoice_items (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  invoice_id        TEXT NOT NULL REFERENCES invoices(id) ON DELETE CASCADE,
  description       TEXT NOT NULL,
  hsn_sac           TEXT,
  quantity          REAL NOT NULL DEFAULT 1,
  unit_price_paise  INTEGER NOT NULL DEFAULT 0,
  discount_paise    INTEGER NOT NULL DEFAULT 0,
  tax_rate_pct      REAL NOT NULL DEFAULT 18,
  tax_paise         INTEGER NOT NULL DEFAULT 0,
  amount_paise      INTEGER NOT NULL DEFAULT 0,
  source_type       TEXT,               -- plan | addon | service
  source_id         TEXT,
  sort_order        INTEGER NOT NULL DEFAULT 100
);
CREATE INDEX idx_invoiceitems_invoice ON invoice_items(invoice_id, sort_order);

-- --------------------------------------------------------------------------
-- Payments — a payment intent plus its gateway transaction attempts.
-- --------------------------------------------------------------------------
CREATE TABLE payments (
  id                  TEXT PRIMARY KEY,
  tenant_id           TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  invoice_id          TEXT REFERENCES invoices(id) ON DELETE SET NULL,
  client_id           TEXT REFERENCES clients(id) ON DELETE SET NULL,
  subscription_id     TEXT REFERENCES subscriptions(id) ON DELETE SET NULL,
  reference_no        TEXT NOT NULL,
  gateway             TEXT NOT NULL
                        CHECK (gateway IN ('razorpay','stripe','cashfree','phonepe','manual','offline')),
  method              TEXT
                        CHECK (method IN ('upi','credit_card','debit_card','net_banking','wallet','emi','bank_transfer','cash','cheque',NULL)),
  amount_paise        INTEGER NOT NULL,
  currency            TEXT NOT NULL DEFAULT 'INR',
  status              TEXT NOT NULL DEFAULT 'pending'
                        CHECK (status IN ('created','pending','authorized','success','failed','cancelled','refunded','partially_refunded','disputed')),
  gateway_order_id    TEXT,
  gateway_payment_id  TEXT,
  gateway_signature   TEXT,
  idempotency_key     TEXT,
  failure_code        TEXT,
  failure_reason      TEXT,
  refunded_paise      INTEGER NOT NULL DEFAULT 0,
  retry_count         INTEGER NOT NULL DEFAULT 0,
  receipt_no          TEXT,
  receipt_key         TEXT,
  paid_at             TEXT,
  initiated_by        TEXT,
  notes_json          TEXT,
  created_at          TEXT NOT NULL,
  updated_at          TEXT NOT NULL,
  UNIQUE (tenant_id, reference_no)
);
CREATE INDEX idx_payments_tenant_status ON payments(tenant_id, status);
CREATE INDEX idx_payments_invoice ON payments(invoice_id);
CREATE INDEX idx_payments_gateway_order ON payments(gateway_order_id);
CREATE UNIQUE INDEX idx_payments_idempotency ON payments(idempotency_key) WHERE idempotency_key IS NOT NULL;

CREATE TABLE payment_transactions (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  payment_id        TEXT NOT NULL REFERENCES payments(id) ON DELETE CASCADE,
  kind              TEXT NOT NULL
                      CHECK (kind IN ('order_created','authorize','capture','fail','refund','chargeback','verify','webhook')),
  status            TEXT NOT NULL,
  amount_paise      INTEGER NOT NULL DEFAULT 0,
  gateway_reference TEXT,
  request_json      TEXT,
  response_json     TEXT,
  error_code        TEXT,
  error_message     TEXT,
  created_at        TEXT NOT NULL
);
CREATE INDEX idx_paytx_payment ON payment_transactions(payment_id, created_at);

-- Every inbound webhook is stored before it is acted on: signature state,
-- raw body and processing outcome. Replays are detected by event_id.
CREATE TABLE webhook_events (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT,
  source            TEXT NOT NULL,      -- razorpay | stripe | meta | whatsapp | exotel | digio ...
  event_id          TEXT,
  event_type        TEXT,
  signature_status  TEXT NOT NULL DEFAULT 'unverified'
                      CHECK (signature_status IN ('unverified','valid','invalid','missing_secret')),
  status            TEXT NOT NULL DEFAULT 'received'
                      CHECK (status IN ('received','processed','ignored','failed','duplicate')),
  payload_json      TEXT NOT NULL,
  headers_json      TEXT,
  error_message     TEXT,
  processed_at      TEXT,
  received_at       TEXT NOT NULL
);
CREATE INDEX idx_webhookevents_source ON webhook_events(source, received_at);
CREATE UNIQUE INDEX idx_webhookevents_dedupe ON webhook_events(source, event_id) WHERE event_id IS NOT NULL;

-- Franchise revenue share, computed from settled invoices.
CREATE TABLE franchise_revenue (
  id                TEXT PRIMARY KEY,
  franchise_id      TEXT NOT NULL REFERENCES franchises(id) ON DELETE CASCADE,
  tenant_id         TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  period_key        TEXT NOT NULL,
  gross_paise       INTEGER NOT NULL DEFAULT 0,
  share_pct         REAL NOT NULL,
  share_paise       INTEGER NOT NULL DEFAULT 0,
  status            TEXT NOT NULL DEFAULT 'accrued'
                      CHECK (status IN ('accrued','approved','paid','disputed')),
  settled_at        TEXT,
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL,
  UNIQUE (franchise_id, tenant_id, period_key)
);

-- ===== 0005_communication_and_support.sql =====

-- =============================================================================
-- 0005 — Notifications, messaging channels, voice notes and support tickets
-- =============================================================================

PRAGMA foreign_keys = ON;

-- --------------------------------------------------------------------------
-- Notification templates — one row per trigger × channel.
-- --------------------------------------------------------------------------
CREATE TABLE notification_templates (
  id              TEXT PRIMARY KEY,
  tenant_id       TEXT REFERENCES tenants(id) ON DELETE CASCADE,  -- NULL = platform default
  trigger_key     TEXT NOT NULL,        -- document.uploaded | payment.due | gst.due_date ...
  channel         TEXT NOT NULL
                    CHECK (channel IN ('email','sms','whatsapp','in_app','push')),
  name            TEXT NOT NULL,
  subject         TEXT,
  body            TEXT NOT NULL,        -- {{placeholders}}
  provider_template_id TEXT,            -- e.g. approved WhatsApp template name
  variables_json  TEXT,
  is_active       INTEGER NOT NULL DEFAULT 1,
  created_at      TEXT NOT NULL,
  updated_at      TEXT NOT NULL
);
CREATE UNIQUE INDEX idx_nt_default ON notification_templates(trigger_key, channel) WHERE tenant_id IS NULL;
CREATE UNIQUE INDEX idx_nt_tenant ON notification_templates(tenant_id, trigger_key, channel) WHERE tenant_id IS NOT NULL;

-- Per-tenant + per-user channel switches (the Notification Settings screen).
CREATE TABLE notification_preferences (
  id            TEXT PRIMARY KEY,
  tenant_id     TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  user_id       TEXT REFERENCES users(id) ON DELETE CASCADE,  -- NULL = tenant-wide default
  trigger_key   TEXT NOT NULL DEFAULT '*',
  email_enabled     INTEGER NOT NULL DEFAULT 1,
  sms_enabled       INTEGER NOT NULL DEFAULT 0,
  whatsapp_enabled  INTEGER NOT NULL DEFAULT 0,
  in_app_enabled    INTEGER NOT NULL DEFAULT 1,
  push_enabled      INTEGER NOT NULL DEFAULT 1,
  quiet_hours_start TEXT,
  quiet_hours_end   TEXT,
  updated_at    TEXT NOT NULL,
  UNIQUE (tenant_id, user_id, trigger_key)
);

-- In-app notification feed.
CREATE TABLE notifications (
  id            TEXT PRIMARY KEY,
  tenant_id     TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  user_id       TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  trigger_key   TEXT NOT NULL,
  title         TEXT NOT NULL,
  body          TEXT,
  severity      TEXT NOT NULL DEFAULT 'info'
                  CHECK (severity IN ('info','success','warning','danger')),
  icon          TEXT,
  link_path     TEXT,
  entity_type   TEXT,
  entity_id     TEXT,
  read_at       TEXT,
  created_at    TEXT NOT NULL
);
CREATE INDEX idx_notifications_user ON notifications(user_id, read_at, created_at);

-- Outbound delivery queue/log across every channel. Nothing is reported as
-- "sent" unless a provider actually accepted it.
CREATE TABLE message_deliveries (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  channel           TEXT NOT NULL CHECK (channel IN ('email','sms','whatsapp','push','in_app')),
  provider          TEXT,               -- ses | msg91 | whatsapp_cloud | fcm
  trigger_key       TEXT,
  template_id       TEXT,
  to_user_id        TEXT,
  to_address        TEXT NOT NULL,      -- email / E.164 / device token
  subject           TEXT,
  body              TEXT,
  attachments_json  TEXT,
  status            TEXT NOT NULL DEFAULT 'queued'
                      CHECK (status IN ('queued','sending','sent','delivered','read','opened','clicked','failed','bounced','skipped','not_configured')),
  provider_message_id TEXT,
  error_code        TEXT,
  error_message     TEXT,
  attempts          INTEGER NOT NULL DEFAULT 0,
  opened_at         TEXT,
  clicked_at        TEXT,
  delivered_at      TEXT,
  entity_type       TEXT,
  entity_id         TEXT,
  client_id         TEXT,
  campaign_id       TEXT,
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL
);
CREATE INDEX idx_deliveries_tenant ON message_deliveries(tenant_id, channel, created_at);
CREATE INDEX idx_deliveries_status ON message_deliveries(status, created_at);
CREATE INDEX idx_deliveries_client ON message_deliveries(client_id, created_at);

-- Automation rules — the trigger→action engine behind Email/SMS automation.
CREATE TABLE automation_rules (
  id              TEXT PRIMARY KEY,
  tenant_id       TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  name            TEXT NOT NULL,
  description     TEXT,
  trigger_key     TEXT NOT NULL,
  conditions_json TEXT,                 -- [{field, op, value}]
  actions_json    TEXT NOT NULL,        -- [{type:'send_email', templateId, delayMinutes}]
  channel         TEXT,
  delay_minutes   INTEGER NOT NULL DEFAULT 0,
  is_active       INTEGER NOT NULL DEFAULT 1,
  last_fired_at   TEXT,
  fire_count      INTEGER NOT NULL DEFAULT 0,
  created_by      TEXT,
  created_at      TEXT NOT NULL,
  updated_at      TEXT NOT NULL
);
CREATE INDEX idx_automation_tenant ON automation_rules(tenant_id, trigger_key, is_active);

-- --------------------------------------------------------------------------
-- WhatsApp Business API (add-on 01)
-- --------------------------------------------------------------------------
CREATE TABLE whatsapp_templates (
  id                  TEXT PRIMARY KEY,
  tenant_id           TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  name                TEXT NOT NULL,
  language            TEXT NOT NULL DEFAULT 'en',
  category            TEXT NOT NULL DEFAULT 'UTILITY'
                        CHECK (category IN ('UTILITY','MARKETING','AUTHENTICATION')),
  header_text         TEXT,
  body_text           TEXT NOT NULL,
  footer_text         TEXT,
  buttons_json        TEXT,
  variables_json      TEXT,
  approval_status     TEXT NOT NULL DEFAULT 'draft'
                        CHECK (approval_status IN ('draft','pending','approved','rejected','disabled')),
  provider_template_id TEXT,
  rejection_reason    TEXT,
  created_at          TEXT NOT NULL,
  updated_at          TEXT NOT NULL,
  UNIQUE (tenant_id, name, language)
);

CREATE TABLE chat_threads (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  channel           TEXT NOT NULL DEFAULT 'whatsapp' CHECK (channel IN ('whatsapp','sms')),
  client_id         TEXT REFERENCES clients(id) ON DELETE SET NULL,
  contact_id        TEXT REFERENCES client_contacts(id) ON DELETE SET NULL,
  phone             TEXT NOT NULL,
  display_name      TEXT,
  assigned_to       TEXT REFERENCES users(id) ON DELETE SET NULL,
  status            TEXT NOT NULL DEFAULT 'open'
                      CHECK (status IN ('open','bot','assigned','snoozed','closed')),
  unread_count      INTEGER NOT NULL DEFAULT 0,
  last_message_at   TEXT,
  last_message_preview TEXT,
  window_expires_at TEXT,               -- the 24h customer-service window
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL,
  UNIQUE (tenant_id, channel, phone)
);
CREATE INDEX idx_chatthreads_tenant ON chat_threads(tenant_id, status, last_message_at);

CREATE TABLE chat_messages (
  id                  TEXT PRIMARY KEY,
  tenant_id           TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  thread_id           TEXT NOT NULL REFERENCES chat_threads(id) ON DELETE CASCADE,
  direction           TEXT NOT NULL CHECK (direction IN ('inbound','outbound')),
  type                TEXT NOT NULL DEFAULT 'text'
                        CHECK (type IN ('text','image','document','audio','video','template','interactive','location','system')),
  body                TEXT,
  media_key           TEXT,
  media_mime          TEXT,
  media_name          TEXT,
  template_id         TEXT,
  sent_by             TEXT REFERENCES users(id) ON DELETE SET NULL,
  is_bot              INTEGER NOT NULL DEFAULT 0,
  provider_message_id TEXT,
  status              TEXT NOT NULL DEFAULT 'queued'
                        CHECK (status IN ('queued','sent','delivered','read','failed','received')),
  error_message       TEXT,
  linked_document_id  TEXT REFERENCES documents(id) ON DELETE SET NULL,
  created_at          TEXT NOT NULL
);
CREATE INDEX idx_chatmessages_thread ON chat_messages(thread_id, created_at);

CREATE TABLE chatbot_flows (
  id            TEXT PRIMARY KEY,
  tenant_id     TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  name          TEXT NOT NULL,
  description   TEXT,
  trigger_keywords_json TEXT,
  nodes_json    TEXT NOT NULL,          -- [{id,type,prompt,options,next,action}]
  entry_node_id TEXT,
  is_active     INTEGER NOT NULL DEFAULT 0,
  fallback_to_human INTEGER NOT NULL DEFAULT 1,
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
);

CREATE TABLE broadcasts (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  channel           TEXT NOT NULL CHECK (channel IN ('whatsapp','sms','email')),
  name              TEXT NOT NULL,
  template_id       TEXT,
  body              TEXT,
  audience_json     TEXT NOT NULL,      -- filter describing the recipient set
  recipient_count   INTEGER NOT NULL DEFAULT 0,
  sent_count        INTEGER NOT NULL DEFAULT 0,
  delivered_count   INTEGER NOT NULL DEFAULT 0,
  failed_count      INTEGER NOT NULL DEFAULT 0,
  status            TEXT NOT NULL DEFAULT 'draft'
                      CHECK (status IN ('draft','scheduled','sending','completed','failed','cancelled')),
  scheduled_at      TEXT,
  started_at        TEXT,
  completed_at      TEXT,
  created_by        TEXT,
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL
);
CREATE INDEX idx_broadcasts_tenant ON broadcasts(tenant_id, status);

-- --------------------------------------------------------------------------
-- Voice notes (add-on 04)
-- --------------------------------------------------------------------------
CREATE TABLE voice_notes (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  client_id         TEXT REFERENCES clients(id) ON DELETE CASCADE,
  entity_type       TEXT,               -- query | document | client | task
  entity_id         TEXT,
  author_id         TEXT REFERENCES users(id) ON DELETE SET NULL,
  storage_key       TEXT NOT NULL,
  mime_type         TEXT NOT NULL DEFAULT 'audio/webm',
  duration_seconds  INTEGER NOT NULL DEFAULT 0,
  size_bytes        INTEGER NOT NULL DEFAULT 0,
  transcript        TEXT,
  transcript_status TEXT NOT NULL DEFAULT 'pending'
                      CHECK (transcript_status IN ('pending','processing','done','failed','not_configured','skipped')),
  transcript_lang   TEXT,
  transcript_confidence REAL,
  created_at        TEXT NOT NULL
);
CREATE INDEX idx_voicenotes_entity ON voice_notes(entity_type, entity_id);
CREATE INDEX idx_voicenotes_client ON voice_notes(client_id, created_at);

-- --------------------------------------------------------------------------
-- Support tickets
-- --------------------------------------------------------------------------
CREATE TABLE support_tickets (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  client_id         TEXT REFERENCES clients(id) ON DELETE SET NULL,
  company_id        TEXT REFERENCES companies(id) ON DELETE SET NULL,
  ticket_no         TEXT NOT NULL,
  subject           TEXT NOT NULL,
  description       TEXT NOT NULL,
  category          TEXT NOT NULL DEFAULT 'general'
                      CHECK (category IN ('general','technical','billing','document','filing','account','feature_request','bug','other')),
  priority          TEXT NOT NULL DEFAULT 'normal'
                      CHECK (priority IN ('low','normal','high','urgent')),
  status            TEXT NOT NULL DEFAULT 'open'
                      CHECK (status IN ('open','in_progress','waiting_customer','waiting_internal','resolved','closed','reopened')),
  raised_by         TEXT REFERENCES users(id) ON DELETE SET NULL,
  assigned_to       TEXT REFERENCES users(id) ON DELETE SET NULL,
  channel           TEXT NOT NULL DEFAULT 'portal'
                      CHECK (channel IN ('portal','email','whatsapp','phone','chat','api')),
  first_response_at TEXT,
  resolved_at       TEXT,
  closed_at         TEXT,
  resolution        TEXT,
  satisfaction_rating INTEGER,
  sla_due_at        TEXT,
  sla_breached      INTEGER NOT NULL DEFAULT 0,
  reopen_count      INTEGER NOT NULL DEFAULT 0,
  message_count     INTEGER NOT NULL DEFAULT 0,
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL,
  UNIQUE (tenant_id, ticket_no)
);
CREATE INDEX idx_tickets_tenant_status ON support_tickets(tenant_id, status);
CREATE INDEX idx_tickets_client ON support_tickets(client_id, status);
CREATE INDEX idx_tickets_assignee ON support_tickets(assigned_to, status);

CREATE TABLE ticket_messages (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  ticket_id         TEXT NOT NULL REFERENCES support_tickets(id) ON DELETE CASCADE,
  author_id         TEXT REFERENCES users(id) ON DELETE SET NULL,
  author_name       TEXT,
  author_kind       TEXT NOT NULL DEFAULT 'agent'
                      CHECK (author_kind IN ('agent','client','system')),
  body              TEXT NOT NULL,
  visibility        TEXT NOT NULL DEFAULT 'shared'
                      CHECK (visibility IN ('shared','internal')),
  attachments_json  TEXT,
  created_at        TEXT NOT NULL
);
CREATE INDEX idx_ticketmessages_ticket ON ticket_messages(ticket_id, created_at);

-- ===== 0006_integrations_ai_leads.sql =====

-- =============================================================================
-- 0006 — Integrations, OAuth, leads, AI modules, API marketplace, calendar
-- =============================================================================

PRAGMA foreign_keys = ON;

-- --------------------------------------------------------------------------
-- Integration registry — one row per tenant × provider. Holds connection
-- state and non-secret config; secrets live in Worker secrets, never here.
-- An integration with no credentials reports status 'not_connected'.
-- --------------------------------------------------------------------------
CREATE TABLE integrations (
  id                  TEXT PRIMARY KEY,
  tenant_id           TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  provider            TEXT NOT NULL,    -- ses | msg91 | whatsapp_cloud | meta_leads | google_sheets ...
  category            TEXT NOT NULL,    -- email | sms | whatsapp | leads | storage | calendar | ai | payments | esign | telephony | dns
  add_on_key          TEXT,             -- the marketplace module that owns it
  display_name        TEXT NOT NULL,
  status              TEXT NOT NULL DEFAULT 'not_connected'
                        CHECK (status IN ('not_connected','pending','connected','error','disabled','expired')),
  config_json         TEXT,             -- non-secret settings (sender id, folder map…)
  credential_ref      TEXT,             -- names of the env secrets this needs
  encrypted_secret    TEXT,             -- AES-GCM blob for tenant-supplied keys
  last_test_at        TEXT,
  last_test_ok        INTEGER,
  last_test_message   TEXT,
  last_sync_at        TEXT,
  last_error          TEXT,
  connected_by        TEXT REFERENCES users(id) ON DELETE SET NULL,
  connected_at        TEXT,
  created_at          TEXT NOT NULL,
  updated_at          TEXT NOT NULL,
  UNIQUE (tenant_id, provider)
);
CREATE INDEX idx_integrations_tenant ON integrations(tenant_id, category, status);

CREATE TABLE oauth_connections (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  integration_id    TEXT REFERENCES integrations(id) ON DELETE CASCADE,
  provider          TEXT NOT NULL,      -- google | microsoft | dropbox | meta | ringcentral
  account_email     TEXT,
  account_id        TEXT,
  scopes            TEXT,
  access_token_enc  TEXT,
  refresh_token_enc TEXT,
  token_type        TEXT,
  expires_at        TEXT,
  status            TEXT NOT NULL DEFAULT 'active'
                      CHECK (status IN ('active','expired','revoked','error')),
  connected_by      TEXT REFERENCES users(id) ON DELETE SET NULL,
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL,
  UNIQUE (tenant_id, provider, account_id)
);

-- OAuth state parameter store — CSRF protection on the redirect round-trip.
CREATE TABLE oauth_states (
  state         TEXT PRIMARY KEY,
  tenant_id     TEXT NOT NULL,
  user_id       TEXT NOT NULL,
  provider      TEXT NOT NULL,
  redirect_path TEXT,
  created_at    TEXT NOT NULL,
  expires_at    TEXT NOT NULL
);

CREATE TABLE integration_sync_logs (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  integration_id    TEXT REFERENCES integrations(id) ON DELETE CASCADE,
  provider          TEXT NOT NULL,
  direction         TEXT NOT NULL CHECK (direction IN ('inbound','outbound','bidirectional')),
  operation         TEXT NOT NULL,
  status            TEXT NOT NULL CHECK (status IN ('started','success','partial','failed','skipped')),
  records_in        INTEGER NOT NULL DEFAULT 0,
  records_out       INTEGER NOT NULL DEFAULT 0,
  records_failed    INTEGER NOT NULL DEFAULT 0,
  detail_json       TEXT,
  error_message     TEXT,
  duration_ms       INTEGER,
  started_at        TEXT NOT NULL,
  finished_at       TEXT
);
CREATE INDEX idx_synclogs_tenant ON integration_sync_logs(tenant_id, provider, started_at);

-- Field mapping for Sheets / Forms / webhook payload → CRM fields.
CREATE TABLE field_mappings (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  integration_id    TEXT REFERENCES integrations(id) ON DELETE CASCADE,
  source_key        TEXT NOT NULL,      -- sheet column / form question id
  source_label      TEXT,
  target_entity     TEXT NOT NULL DEFAULT 'lead'
                      CHECK (target_entity IN ('lead','client','company','contact','document','task')),
  target_field      TEXT NOT NULL,
  transform         TEXT,               -- trim | upper | phone_e164 | date_iso
  is_required       INTEGER NOT NULL DEFAULT 0,
  default_value     TEXT,
  sort_order        INTEGER NOT NULL DEFAULT 100,
  created_at        TEXT NOT NULL
);
CREATE INDEX idx_fieldmappings_integration ON field_mappings(integration_id, sort_order);

-- --------------------------------------------------------------------------
-- Leads & campaigns (Meta Lead Ads, Google Forms, website forms, Sheets)
-- --------------------------------------------------------------------------
CREATE TABLE campaigns (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  external_id       TEXT,
  source            TEXT NOT NULL
                      CHECK (source IN ('meta_ads','google_ads','website','google_form','sheet','referral','manual','other')),
  name              TEXT NOT NULL,
  platform          TEXT,               -- facebook | instagram | web
  status            TEXT NOT NULL DEFAULT 'active'
                      CHECK (status IN ('active','paused','completed','archived')),
  spend_paise       INTEGER NOT NULL DEFAULT 0,
  lead_count        INTEGER NOT NULL DEFAULT 0,
  converted_count   INTEGER NOT NULL DEFAULT 0,
  started_at        TEXT,
  ended_at          TEXT,
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL
);
CREATE INDEX idx_campaigns_tenant ON campaigns(tenant_id, source);

CREATE TABLE leads (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  campaign_id       TEXT REFERENCES campaigns(id) ON DELETE SET NULL,
  external_id       TEXT,               -- Meta leadgen id / form response id
  source            TEXT NOT NULL DEFAULT 'manual'
                      CHECK (source IN ('meta_ads','google_form','website_form','sheet','whatsapp','call','referral','manual','api','other')),
  full_name         TEXT NOT NULL,
  email             TEXT,
  phone             TEXT,
  company_name      TEXT,
  city              TEXT,
  message           TEXT,
  payload_json      TEXT,               -- the raw captured submission
  utm_source        TEXT,
  utm_medium        TEXT,
  utm_campaign      TEXT,
  utm_term          TEXT,
  utm_content       TEXT,
  page_url          TEXT,
  status            TEXT NOT NULL DEFAULT 'new'
                      CHECK (status IN ('new','contacted','qualified','proposal','won','lost','duplicate','spam')),
  assigned_to       TEXT REFERENCES users(id) ON DELETE SET NULL,
  assigned_at       TEXT,
  duplicate_of      TEXT REFERENCES leads(id) ON DELETE SET NULL,
  merged_into       TEXT REFERENCES leads(id) ON DELETE SET NULL,
  converted_client_id TEXT REFERENCES clients(id) ON DELETE SET NULL,
  converted_at      TEXT,
  score             INTEGER,
  tags_json         TEXT,
  last_contacted_at TEXT,
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL
);
CREATE INDEX idx_leads_tenant_status ON leads(tenant_id, status, created_at);
CREATE INDEX idx_leads_assignee ON leads(assigned_to, status);
CREATE INDEX idx_leads_phone ON leads(tenant_id, phone);
CREATE INDEX idx_leads_email ON leads(tenant_id, email);
CREATE UNIQUE INDEX idx_leads_external ON leads(tenant_id, source, external_id) WHERE external_id IS NOT NULL;

CREATE TABLE lead_assignment_rules (
  id              TEXT PRIMARY KEY,
  tenant_id       TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  name            TEXT NOT NULL,
  priority        INTEGER NOT NULL DEFAULT 100,
  conditions_json TEXT,                 -- source/campaign/city filters
  strategy        TEXT NOT NULL DEFAULT 'round_robin'
                    CHECK (strategy IN ('round_robin','least_loaded','specific_user','branch_manager')),
  target_user_id  TEXT REFERENCES users(id) ON DELETE SET NULL,
  pool_json       TEXT,                 -- user ids in the rotation
  last_assigned_index INTEGER NOT NULL DEFAULT 0,
  is_active       INTEGER NOT NULL DEFAULT 1,
  created_at      TEXT NOT NULL,
  updated_at      TEXT NOT NULL
);

-- Inbound webhook endpoints a tenant can hand to a website or form builder.
CREATE TABLE webhook_endpoints (
  id              TEXT PRIMARY KEY,
  tenant_id       TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  slug            TEXT NOT NULL UNIQUE, -- /webhooks/form/{slug}
  name            TEXT NOT NULL,
  kind            TEXT NOT NULL DEFAULT 'website_form'
                    CHECK (kind IN ('website_form','google_form','sheet','custom')),
  secret_hash     TEXT,
  target_entity   TEXT NOT NULL DEFAULT 'lead',
  is_active       INTEGER NOT NULL DEFAULT 1,
  request_count   INTEGER NOT NULL DEFAULT 0,
  last_request_at TEXT,
  created_by      TEXT,
  created_at      TEXT NOT NULL,
  updated_at      TEXT NOT NULL
);
CREATE INDEX idx_webhookendpoints_tenant ON webhook_endpoints(tenant_id);

-- --------------------------------------------------------------------------
-- AI modules (add-ons 09–12) — every AI output is stored with its confidence
-- and a human review state. Nothing an AI produces is treated as verified.
-- --------------------------------------------------------------------------
CREATE TABLE ocr_extractions (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  document_id       TEXT NOT NULL REFERENCES documents(id) ON DELETE CASCADE,
  version_id        TEXT REFERENCES document_versions(id) ON DELETE SET NULL,
  profile           TEXT NOT NULL,      -- gst_invoice | bank_statement | pan | aadhaar
  provider          TEXT NOT NULL DEFAULT 'google_vision',
  status            TEXT NOT NULL DEFAULT 'queued'
                      CHECK (status IN ('queued','processing','done','failed','not_configured')),
  overall_confidence REAL,
  fields_json       TEXT,               -- [{key,label,value,confidence,bbox}]
  raw_text          TEXT,
  review_status     TEXT NOT NULL DEFAULT 'pending'
                      CHECK (review_status IN ('pending','accepted','edited','rejected')),
  reviewed_by       TEXT REFERENCES users(id) ON DELETE SET NULL,
  reviewed_at       TEXT,
  applied_to_records INTEGER NOT NULL DEFAULT 0,
  error_message     TEXT,
  duration_ms       INTEGER,
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL
);
CREATE INDEX idx_ocr_document ON ocr_extractions(document_id);
CREATE INDEX idx_ocr_tenant_review ON ocr_extractions(tenant_id, review_status);

CREATE TABLE ai_verifications (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  document_id       TEXT NOT NULL REFERENCES documents(id) ON DELETE CASCADE,
  version_id        TEXT REFERENCES document_versions(id) ON DELETE SET NULL,
  status            TEXT NOT NULL DEFAULT 'queued'
                      CHECK (status IN ('queued','processing','clean','flagged','failed','not_configured')),
  confidence        REAL,
  checks_json       TEXT,               -- [{check,result,detail}]
  flags_json        TEXT,               -- [{severity,code,message,page}]
  flag_count        INTEGER NOT NULL DEFAULT 0,
  recommendation    TEXT
                      CHECK (recommendation IN ('pre_approve','review','reject',NULL)),
  provider          TEXT,
  error_message     TEXT,
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL
);
CREATE INDEX idx_aiverify_document ON ai_verifications(document_id);

-- AI assistant conversations (GST/TDS assistant, ask-your-data).
CREATE TABLE ai_conversations (
  id            TEXT PRIMARY KEY,
  tenant_id     TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  user_id       TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  kind          TEXT NOT NULL DEFAULT 'tax_assistant'
                  CHECK (kind IN ('tax_assistant','ask_your_data','call_summary','report_draft')),
  title         TEXT,
  context_json  TEXT,                   -- clientId/periodId the chat is scoped to
  message_count INTEGER NOT NULL DEFAULT 0,
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
);
CREATE INDEX idx_aiconv_user ON ai_conversations(user_id, updated_at);

CREATE TABLE ai_messages (
  id              TEXT PRIMARY KEY,
  tenant_id       TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  conversation_id TEXT NOT NULL REFERENCES ai_conversations(id) ON DELETE CASCADE,
  role            TEXT NOT NULL CHECK (role IN ('user','assistant','system')),
  content         TEXT NOT NULL,
  -- Provenance: which figures came from verified records vs. model generation.
  citations_json  TEXT,
  is_verified_data INTEGER NOT NULL DEFAULT 0,
  disclaimer      TEXT,
  model           TEXT,
  tokens_in       INTEGER,
  tokens_out      INTEGER,
  latency_ms      INTEGER,
  error_message   TEXT,
  created_at      TEXT NOT NULL
);
CREATE INDEX idx_aimessages_conv ON ai_messages(conversation_id, created_at);

CREATE TABLE ai_insights (
  id            TEXT PRIMARY KEY,
  tenant_id     TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  kind          TEXT NOT NULL
                  CHECK (kind IN ('digest','churn_risk','revenue_forecast','workload_forecast','anomaly','opportunity')),
  title         TEXT NOT NULL,
  body          TEXT NOT NULL,
  severity      TEXT NOT NULL DEFAULT 'info'
                  CHECK (severity IN ('info','success','warning','danger')),
  entity_type   TEXT,
  entity_id     TEXT,
  metrics_json  TEXT,
  confidence    REAL,
  period_key    TEXT,
  generated_by  TEXT NOT NULL DEFAULT 'rules'
                  CHECK (generated_by IN ('rules','llm')),
  model         TEXT,
  acknowledged_by TEXT,
  acknowledged_at TEXT,
  dismissed_at  TEXT,
  created_at    TEXT NOT NULL
);
CREATE INDEX idx_aiinsights_tenant ON ai_insights(tenant_id, created_at);

-- --------------------------------------------------------------------------
-- e-Sign (add-on 14)
-- --------------------------------------------------------------------------
CREATE TABLE esign_requests (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  client_id         TEXT REFERENCES clients(id) ON DELETE SET NULL,
  document_id       TEXT REFERENCES documents(id) ON DELETE SET NULL,
  report_id         TEXT REFERENCES reports(id) ON DELETE SET NULL,
  reference_no      TEXT NOT NULL,
  title             TEXT NOT NULL,
  provider          TEXT NOT NULL DEFAULT 'digio'
                      CHECK (provider IN ('digio','leegality','other')),
  method            TEXT NOT NULL DEFAULT 'aadhaar_esign'
                      CHECK (method IN ('aadhaar_esign','dsc','electronic')),
  status            TEXT NOT NULL DEFAULT 'draft'
                      CHECK (status IN ('draft','sent','partially_signed','signed','declined','expired','failed','not_configured')),
  source_key        TEXT,
  signed_key        TEXT,
  provider_request_id TEXT,
  sequential        INTEGER NOT NULL DEFAULT 1,
  expires_at        TEXT,
  completed_at      TEXT,
  created_by        TEXT REFERENCES users(id) ON DELETE SET NULL,
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL,
  UNIQUE (tenant_id, reference_no)
);

CREATE TABLE esign_signers (
  id              TEXT PRIMARY KEY,
  tenant_id       TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  request_id      TEXT NOT NULL REFERENCES esign_requests(id) ON DELETE CASCADE,
  name            TEXT NOT NULL,
  email           TEXT,
  phone           TEXT,
  sequence        INTEGER NOT NULL DEFAULT 1,
  status          TEXT NOT NULL DEFAULT 'pending'
                    CHECK (status IN ('pending','sent','viewed','signed','declined','expired')),
  signed_at       TEXT,
  declined_reason TEXT,
  ip              TEXT,
  provider_signer_id TEXT,
  created_at      TEXT NOT NULL
);
CREATE INDEX idx_esignsigners_request ON esign_signers(request_id, sequence);

-- --------------------------------------------------------------------------
-- Cloud storage sync (add-ons 15–17)
-- --------------------------------------------------------------------------
CREATE TABLE storage_folder_maps (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  integration_id    TEXT NOT NULL REFERENCES integrations(id) ON DELETE CASCADE,
  provider          TEXT NOT NULL CHECK (provider IN ('google_drive','dropbox','onedrive')),
  scope_type        TEXT NOT NULL DEFAULT 'tenant'
                      CHECK (scope_type IN ('tenant','company','client')),
  scope_id          TEXT,
  remote_folder_id  TEXT,
  remote_path       TEXT NOT NULL,
  auto_sync         INTEGER NOT NULL DEFAULT 1,
  sync_on           TEXT NOT NULL DEFAULT 'verified'
                      CHECK (sync_on IN ('upload','verified','approved')),
  preserve_versions INTEGER NOT NULL DEFAULT 1,
  last_sync_at      TEXT,
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL
);
CREATE INDEX idx_folder_maps_tenant ON storage_folder_maps(tenant_id, provider);

CREATE TABLE storage_sync_items (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  map_id            TEXT NOT NULL REFERENCES storage_folder_maps(id) ON DELETE CASCADE,
  document_id       TEXT REFERENCES documents(id) ON DELETE CASCADE,
  version_id        TEXT REFERENCES document_versions(id) ON DELETE SET NULL,
  remote_file_id    TEXT,
  remote_path       TEXT,
  status            TEXT NOT NULL DEFAULT 'pending'
                      CHECK (status IN ('pending','syncing','synced','failed','skipped')),
  error_message     TEXT,
  synced_at         TEXT,
  created_at        TEXT NOT NULL
);
CREATE INDEX idx_syncitems_map ON storage_sync_items(map_id, status);

-- --------------------------------------------------------------------------
-- Calendar (add-on 22)
-- --------------------------------------------------------------------------
CREATE TABLE calendar_events (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  client_id         TEXT REFERENCES clients(id) ON DELETE SET NULL,
  owner_id          TEXT REFERENCES users(id) ON DELETE CASCADE,
  title             TEXT NOT NULL,
  description       TEXT,
  kind              TEXT NOT NULL DEFAULT 'meeting'
                      CHECK (kind IN ('meeting','due_date','reminder','visit','call','filing_deadline')),
  location          TEXT,
  starts_at         TEXT NOT NULL,
  ends_at           TEXT NOT NULL,
  all_day           INTEGER NOT NULL DEFAULT 0,
  attendees_json    TEXT,
  reminder_minutes  INTEGER NOT NULL DEFAULT 30,
  status            TEXT NOT NULL DEFAULT 'confirmed'
                      CHECK (status IN ('tentative','confirmed','cancelled')),
  provider          TEXT CHECK (provider IN ('google','outlook',NULL)),
  provider_event_id TEXT,
  sync_status       TEXT NOT NULL DEFAULT 'local'
                      CHECK (sync_status IN ('local','pending','synced','failed','not_configured')),
  source_type       TEXT,
  source_id         TEXT,
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL
);
CREATE INDEX idx_calevents_owner ON calendar_events(owner_id, starts_at);
CREATE INDEX idx_calevents_tenant ON calendar_events(tenant_id, starts_at);

-- --------------------------------------------------------------------------
-- API Marketplace (add-on 24)
-- --------------------------------------------------------------------------
CREATE TABLE api_keys (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  name              TEXT NOT NULL,
  key_prefix        TEXT NOT NULL,      -- shown in the UI; the rest is never stored
  key_hash          TEXT NOT NULL UNIQUE,
  scopes_json       TEXT NOT NULL,      -- ["clients.read","documents.write"]
  rate_limit_per_min INTEGER NOT NULL DEFAULT 60,
  allowed_ips_json  TEXT,
  status            TEXT NOT NULL DEFAULT 'active'
                      CHECK (status IN ('active','revoked','expired')),
  last_used_at      TEXT,
  request_count     INTEGER NOT NULL DEFAULT 0,
  expires_at        TEXT,
  created_by        TEXT REFERENCES users(id) ON DELETE SET NULL,
  created_at        TEXT NOT NULL,
  revoked_at        TEXT,
  revoked_by        TEXT
);
CREATE INDEX idx_apikeys_tenant ON api_keys(tenant_id, status);

CREATE TABLE api_usage (
  id            TEXT PRIMARY KEY,
  tenant_id     TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  api_key_id    TEXT REFERENCES api_keys(id) ON DELETE CASCADE,
  method        TEXT NOT NULL,
  path          TEXT NOT NULL,
  status_code   INTEGER NOT NULL,
  duration_ms   INTEGER,
  ip            TEXT,
  user_agent    TEXT,
  error_code    TEXT,
  bucket_hour   TEXT NOT NULL,          -- YYYY-MM-DDTHH for cheap rollups
  created_at    TEXT NOT NULL
);
CREATE INDEX idx_apiusage_key ON api_usage(api_key_id, bucket_hour);
CREATE INDEX idx_apiusage_tenant ON api_usage(tenant_id, bucket_hour);

-- ===== 0007_cloud_calling.sql =====

-- =============================================================================
-- 0007 — Cloud Calling & Call Recording System
-- Covers every capability in the addendum's 28-feature grouped list.
-- =============================================================================

PRAGMA foreign_keys = ON;

-- --------------------------------------------------------------------------
-- Telephony settings — one active provider per tenant, from the seven the
-- addendum names. Provider-specific logic lives behind TelephonyProvider.
-- --------------------------------------------------------------------------
CREATE TABLE telephony_settings (
  tenant_id             TEXT PRIMARY KEY REFERENCES tenants(id) ON DELETE CASCADE,
  provider              TEXT NOT NULL DEFAULT 'exotel'
                          CHECK (provider IN ('exotel','knowlarity','myoperator','twilio','plivo','ringcentral','aircall')),
  status                TEXT NOT NULL DEFAULT 'not_connected'
                          CHECK (status IN ('not_connected','connected','error','disabled')),
  caller_id             TEXT,
  virtual_numbers_json  TEXT,
  recording_mode        TEXT NOT NULL DEFAULT 'automatic'
                          CHECK (recording_mode IN ('automatic','manual','disabled')),
  recording_retention_days INTEGER NOT NULL DEFAULT 365,
  transcription_enabled INTEGER NOT NULL DEFAULT 0,
  ai_summary_enabled    INTEGER NOT NULL DEFAULT 0,
  sentiment_enabled     INTEGER NOT NULL DEFAULT 0,
  auto_create_task      INTEGER NOT NULL DEFAULT 1,
  auto_log_activity     INTEGER NOT NULL DEFAULT 1,
  ivr_enabled           INTEGER NOT NULL DEFAULT 0,
  voicemail_enabled     INTEGER NOT NULL DEFAULT 1,
  business_hours_json   TEXT,
  webhook_secret_set    INTEGER NOT NULL DEFAULT 0,
  last_test_at          TEXT,
  last_test_ok          INTEGER,
  last_test_message     TEXT,
  updated_by            TEXT,
  updated_at            TEXT NOT NULL
);

-- Per-agent calling identity (extension / agent id at the provider).
CREATE TABLE telephony_agents (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  user_id           TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  extension         TEXT,
  provider_agent_id TEXT,
  direct_number     TEXT,
  presence          TEXT NOT NULL DEFAULT 'offline'
                      CHECK (presence IN ('offline','available','busy','on_call','away','dnd')),
  presence_updated_at TEXT,
  is_active         INTEGER NOT NULL DEFAULT 1,
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL,
  UNIQUE (tenant_id, user_id)
);

-- --------------------------------------------------------------------------
-- Dispositions & tags — configurable per tenant, used to close out a call.
-- --------------------------------------------------------------------------
CREATE TABLE call_dispositions (
  id            TEXT PRIMARY KEY,
  tenant_id     TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  key           TEXT NOT NULL,
  label         TEXT NOT NULL,
  outcome       TEXT NOT NULL DEFAULT 'neutral'
                  CHECK (outcome IN ('positive','neutral','negative')),
  requires_follow_up INTEGER NOT NULL DEFAULT 0,
  colour        TEXT,
  sort_order    INTEGER NOT NULL DEFAULT 100,
  is_active     INTEGER NOT NULL DEFAULT 1,
  created_at    TEXT NOT NULL,
  UNIQUE (tenant_id, key)
);

CREATE TABLE call_tags (
  id            TEXT PRIMARY KEY,
  tenant_id     TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  label         TEXT NOT NULL,
  colour        TEXT,
  usage_count   INTEGER NOT NULL DEFAULT 0,
  created_at    TEXT NOT NULL,
  UNIQUE (tenant_id, label)
);

-- --------------------------------------------------------------------------
-- Call records — the spine of the calling module.
-- --------------------------------------------------------------------------
CREATE TABLE call_records (
  id                  TEXT PRIMARY KEY,
  tenant_id           TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  company_id          TEXT REFERENCES companies(id) ON DELETE SET NULL,
  client_id           TEXT REFERENCES clients(id) ON DELETE SET NULL,
  contact_id          TEXT REFERENCES client_contacts(id) ON DELETE SET NULL,
  lead_id             TEXT REFERENCES leads(id) ON DELETE SET NULL,
  agent_id            TEXT REFERENCES users(id) ON DELETE SET NULL,
  provider            TEXT NOT NULL,
  provider_call_id    TEXT,
  direction           TEXT NOT NULL CHECK (direction IN ('inbound','outbound','internal')),
  from_number         TEXT NOT NULL,
  to_number           TEXT NOT NULL,
  virtual_number      TEXT,
  status              TEXT NOT NULL DEFAULT 'initiated'
                        CHECK (status IN ('initiated','ringing','in_progress','on_hold','completed','missed','busy','no_answer','failed','cancelled','voicemail')),
  -- "Live Call Status" is this column plus started_at, polled by the UI.
  answered            INTEGER NOT NULL DEFAULT 0,
  started_at          TEXT,
  answered_at         TEXT,
  ended_at            TEXT,
  duration_seconds    INTEGER NOT NULL DEFAULT 0,
  talk_seconds        INTEGER NOT NULL DEFAULT 0,
  hold_seconds        INTEGER NOT NULL DEFAULT 0,
  wait_seconds        INTEGER NOT NULL DEFAULT 0,
  is_muted            INTEGER NOT NULL DEFAULT 0,
  is_on_hold          INTEGER NOT NULL DEFAULT 0,
  is_recording        INTEGER NOT NULL DEFAULT 0,
  recording_enabled   INTEGER NOT NULL DEFAULT 1,
  transferred_to      TEXT REFERENCES users(id) ON DELETE SET NULL,
  transferred_at      TEXT,
  transfer_type       TEXT CHECK (transfer_type IN ('warm','cold',NULL)),
  is_conference       INTEGER NOT NULL DEFAULT 0,
  conference_id       TEXT,
  ivr_flow_id         TEXT,
  ivr_path_json       TEXT,
  disposition_id      TEXT REFERENCES call_dispositions(id) ON DELETE SET NULL,
  disposition_key     TEXT,
  tags_json           TEXT,
  entity_type         TEXT,             -- what the call was about
  entity_id           TEXT,
  follow_up_task_id   TEXT REFERENCES tasks(id) ON DELETE SET NULL,
  follow_up_at        TEXT,
  missed_handled      INTEGER NOT NULL DEFAULT 0,
  missed_callback_at  TEXT,
  cost_paise          INTEGER NOT NULL DEFAULT 0,
  quality_rating      INTEGER,
  created_at          TEXT NOT NULL,
  updated_at          TEXT NOT NULL
);
CREATE INDEX idx_calls_tenant_created ON call_records(tenant_id, created_at);
CREATE INDEX idx_calls_client ON call_records(client_id, created_at);
CREATE INDEX idx_calls_agent ON call_records(agent_id, created_at);
CREATE INDEX idx_calls_status ON call_records(tenant_id, status);
CREATE INDEX idx_calls_direction ON call_records(tenant_id, direction, created_at);
CREATE UNIQUE INDEX idx_calls_provider ON call_records(provider, provider_call_id) WHERE provider_call_id IS NOT NULL;

CREATE TABLE call_recordings (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  call_id           TEXT NOT NULL REFERENCES call_records(id) ON DELETE CASCADE,
  storage_key       TEXT,               -- R2 key once fetched from the provider
  provider_url      TEXT,               -- provider-hosted URL, never exposed raw
  mime_type         TEXT NOT NULL DEFAULT 'audio/mpeg',
  size_bytes        INTEGER NOT NULL DEFAULT 0,
  duration_seconds  INTEGER NOT NULL DEFAULT 0,
  status            TEXT NOT NULL DEFAULT 'pending'
                      CHECK (status IN ('pending','available','archived','deleted','failed','not_configured')),
  waveform_json     TEXT,
  retention_until   TEXT,
  downloaded_count  INTEGER NOT NULL DEFAULT 0,
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL
);
CREATE INDEX idx_recordings_call ON call_recordings(call_id);
CREATE INDEX idx_recordings_tenant ON call_recordings(tenant_id, status);

CREATE TABLE call_notes (
  id            TEXT PRIMARY KEY,
  tenant_id     TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  call_id       TEXT NOT NULL REFERENCES call_records(id) ON DELETE CASCADE,
  author_id     TEXT REFERENCES users(id) ON DELETE SET NULL,
  body          TEXT NOT NULL,
  is_during_call INTEGER NOT NULL DEFAULT 0,
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
);
CREATE INDEX idx_callnotes_call ON call_notes(call_id, created_at);

CREATE TABLE call_transcripts (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  call_id           TEXT NOT NULL REFERENCES call_records(id) ON DELETE CASCADE,
  provider          TEXT NOT NULL DEFAULT 'google_speech',
  status            TEXT NOT NULL DEFAULT 'queued'
                      CHECK (status IN ('queued','processing','done','failed','not_configured')),
  language          TEXT,
  full_text         TEXT,
  segments_json     TEXT,               -- [{start,end,speaker,text,confidence}]
  confidence        REAL,
  word_count        INTEGER,
  error_message     TEXT,
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL
);
CREATE INDEX idx_transcripts_call ON call_transcripts(call_id);

CREATE TABLE call_ai_analysis (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  call_id           TEXT NOT NULL REFERENCES call_records(id) ON DELETE CASCADE,
  status            TEXT NOT NULL DEFAULT 'queued'
                      CHECK (status IN ('queued','processing','done','failed','not_configured')),
  summary           TEXT,
  key_points_json   TEXT,
  action_items_json TEXT,
  sentiment         TEXT CHECK (sentiment IN ('positive','neutral','negative','mixed',NULL)),
  sentiment_score   REAL,               -- -1..1
  topics_json       TEXT,
  next_step         TEXT,
  model             TEXT,
  confidence        REAL,
  error_message     TEXT,
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL
);
CREATE INDEX idx_callai_call ON call_ai_analysis(call_id);
CREATE INDEX idx_callai_sentiment ON call_ai_analysis(tenant_id, sentiment);

-- --------------------------------------------------------------------------
-- IVR & voicemail
-- --------------------------------------------------------------------------
CREATE TABLE ivr_flows (
  id            TEXT PRIMARY KEY,
  tenant_id     TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  name          TEXT NOT NULL,
  description   TEXT,
  greeting_text TEXT,
  greeting_key  TEXT,
  nodes_json    TEXT NOT NULL,          -- [{digit,label,action,target}]
  business_hours_json TEXT,
  after_hours_action TEXT NOT NULL DEFAULT 'voicemail'
                      CHECK (after_hours_action IN ('voicemail','message','forward','hangup')),
  is_active     INTEGER NOT NULL DEFAULT 0,
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
);

CREATE TABLE voicemails (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  call_id           TEXT REFERENCES call_records(id) ON DELETE SET NULL,
  client_id         TEXT REFERENCES clients(id) ON DELETE SET NULL,
  from_number       TEXT NOT NULL,
  to_number         TEXT,
  assigned_to       TEXT REFERENCES users(id) ON DELETE SET NULL,
  storage_key       TEXT,
  provider_url      TEXT,
  duration_seconds  INTEGER NOT NULL DEFAULT 0,
  transcript        TEXT,
  status            TEXT NOT NULL DEFAULT 'new'
                      CHECK (status IN ('new','heard','actioned','archived')),
  heard_at          TEXT,
  created_at        TEXT NOT NULL
);
CREATE INDEX idx_voicemails_tenant ON voicemails(tenant_id, status, created_at);

-- Rolled-up daily calling metrics — keeps the analytics screens cheap.
CREATE TABLE call_metrics_daily (
  id                  TEXT PRIMARY KEY,
  tenant_id           TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  agent_id            TEXT REFERENCES users(id) ON DELETE CASCADE,
  day                 TEXT NOT NULL,    -- YYYY-MM-DD
  total_calls         INTEGER NOT NULL DEFAULT 0,
  inbound_calls       INTEGER NOT NULL DEFAULT 0,
  outbound_calls      INTEGER NOT NULL DEFAULT 0,
  missed_calls        INTEGER NOT NULL DEFAULT 0,
  answered_calls      INTEGER NOT NULL DEFAULT 0,
  total_duration_sec  INTEGER NOT NULL DEFAULT 0,
  avg_duration_sec    INTEGER NOT NULL DEFAULT 0,
  positive_count      INTEGER NOT NULL DEFAULT 0,
  neutral_count       INTEGER NOT NULL DEFAULT 0,
  negative_count      INTEGER NOT NULL DEFAULT 0,
  follow_ups_created  INTEGER NOT NULL DEFAULT 0,
  updated_at          TEXT NOT NULL,
  UNIQUE (tenant_id, agent_id, day)
);
CREATE INDEX idx_callmetrics_tenant_day ON call_metrics_daily(tenant_id, day);

-- ===== 0008_audit_ops_settings.sql =====

-- =============================================================================
-- 0008 — Audit trail, attendance, white label, backups, settings, system logs
-- =============================================================================

PRAGMA foreign_keys = ON;

-- --------------------------------------------------------------------------
-- Audit logs — the compliance record. Tamper-evident by hash chaining: each
-- row stores the hash of the previous row for its tenant, so any deletion or
-- edit breaks the chain and is detectable (`/api/audit/verify-chain`).
-- Retention is configurable up to 7 years (Advanced Audit Logs add-on).
-- --------------------------------------------------------------------------
CREATE TABLE audit_logs (
  id              TEXT PRIMARY KEY,
  tenant_id       TEXT,
  sequence        INTEGER NOT NULL,
  actor_id        TEXT,
  actor_name      TEXT,
  actor_role      TEXT,
  actor_type      TEXT NOT NULL DEFAULT 'user'
                    CHECK (actor_type IN ('user','system','api_key','webhook','cron','anonymous')),
  action          TEXT NOT NULL,        -- auth.login | document.verify | settings.update ...
  category        TEXT NOT NULL DEFAULT 'general',
  entity_type     TEXT,
  entity_id       TEXT,
  entity_label    TEXT,
  old_value_json  TEXT,
  new_value_json  TEXT,
  severity        TEXT NOT NULL DEFAULT 'info'
                    CHECK (severity IN ('debug','info','notice','warning','critical')),
  result          TEXT NOT NULL DEFAULT 'success'
                    CHECK (result IN ('success','failure','denied')),
  ip              TEXT,
  user_agent      TEXT,
  session_id      TEXT,
  request_id      TEXT,
  metadata_json   TEXT,
  prev_hash       TEXT,
  hash            TEXT NOT NULL,
  retain_until    TEXT,
  created_at      TEXT NOT NULL
);
CREATE INDEX idx_audit_tenant_seq ON audit_logs(tenant_id, sequence);
CREATE INDEX idx_audit_tenant_created ON audit_logs(tenant_id, created_at);
CREATE INDEX idx_audit_actor ON audit_logs(actor_id, created_at);
CREATE INDEX idx_audit_entity ON audit_logs(entity_type, entity_id);
CREATE INDEX idx_audit_action ON audit_logs(tenant_id, action, created_at);

-- Platform-level operational log, separate from the tenant audit trail.
CREATE TABLE system_logs (
  id            TEXT PRIMARY KEY,
  level         TEXT NOT NULL CHECK (level IN ('debug','info','warn','error','fatal')),
  source        TEXT NOT NULL,          -- worker | cron | webhook | integration
  event         TEXT NOT NULL,
  message       TEXT NOT NULL,
  tenant_id     TEXT,
  request_id    TEXT,
  path          TEXT,
  status_code   INTEGER,
  duration_ms   INTEGER,
  context_json  TEXT,
  stack         TEXT,
  created_at    TEXT NOT NULL
);
CREATE INDEX idx_syslogs_created ON system_logs(created_at);
CREATE INDEX idx_syslogs_level ON system_logs(level, created_at);

-- --------------------------------------------------------------------------
-- Backups (Admin → Backup & Restore)
-- --------------------------------------------------------------------------
CREATE TABLE backups (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT REFERENCES tenants(id) ON DELETE CASCADE,  -- NULL = platform-wide
  kind              TEXT NOT NULL DEFAULT 'full'
                      CHECK (kind IN ('full','database','documents','settings')),
  scope             TEXT NOT NULL DEFAULT 'tenant'
                      CHECK (scope IN ('platform','tenant')),
  status            TEXT NOT NULL DEFAULT 'queued'
                      CHECK (status IN ('queued','running','completed','failed','expired','restored')),
  trigger           TEXT NOT NULL DEFAULT 'manual'
                      CHECK (trigger IN ('manual','scheduled')),
  storage_key       TEXT,
  size_bytes        INTEGER NOT NULL DEFAULT 0,
  table_count       INTEGER NOT NULL DEFAULT 0,
  row_count         INTEGER NOT NULL DEFAULT 0,
  document_count    INTEGER NOT NULL DEFAULT 0,
  checksum_sha256   TEXT,
  manifest_json     TEXT,
  error_message     TEXT,
  started_at        TEXT,
  completed_at      TEXT,
  expires_at        TEXT,
  created_by        TEXT,
  created_at        TEXT NOT NULL
);
CREATE INDEX idx_backups_tenant ON backups(tenant_id, created_at);

CREATE TABLE restore_jobs (
  id            TEXT PRIMARY KEY,
  tenant_id     TEXT REFERENCES tenants(id) ON DELETE CASCADE,
  backup_id     TEXT NOT NULL REFERENCES backups(id) ON DELETE CASCADE,
  mode          TEXT NOT NULL DEFAULT 'dry_run'
                  CHECK (mode IN ('dry_run','restore')),
  status        TEXT NOT NULL DEFAULT 'queued'
                  CHECK (status IN ('queued','running','completed','failed','cancelled')),
  tables_json   TEXT,
  report_json   TEXT,
  error_message TEXT,
  confirmed_by  TEXT,
  started_at    TEXT,
  completed_at  TEXT,
  created_by    TEXT,
  created_at    TEXT NOT NULL
);

-- --------------------------------------------------------------------------
-- GPS attendance & field visits (add-on 21)
-- --------------------------------------------------------------------------
CREATE TABLE attendance (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  user_id           TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  branch_id         TEXT REFERENCES branches(id) ON DELETE SET NULL,
  day               TEXT NOT NULL,      -- YYYY-MM-DD
  check_in_at       TEXT,
  check_in_lat      REAL,
  check_in_lng      REAL,
  check_in_accuracy REAL,
  check_in_address  TEXT,
  check_in_within_geofence INTEGER,
  check_out_at      TEXT,
  check_out_lat     REAL,
  check_out_lng     REAL,
  check_out_address TEXT,
  check_out_within_geofence INTEGER,
  worked_minutes    INTEGER NOT NULL DEFAULT 0,
  travel_km         REAL NOT NULL DEFAULT 0,
  visit_count       INTEGER NOT NULL DEFAULT 0,
  status            TEXT NOT NULL DEFAULT 'present'
                      CHECK (status IN ('present','half_day','absent','leave','holiday','remote','pending')),
  notes             TEXT,
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL,
  UNIQUE (user_id, day)
);
CREATE INDEX idx_attendance_tenant_day ON attendance(tenant_id, day);

CREATE TABLE gps_visits (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  attendance_id     TEXT REFERENCES attendance(id) ON DELETE SET NULL,
  user_id           TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  client_id         TEXT REFERENCES clients(id) ON DELETE SET NULL,
  purpose           TEXT NOT NULL DEFAULT 'document_collection'
                      CHECK (purpose IN ('document_collection','meeting','audit','delivery','other')),
  checked_in_at     TEXT NOT NULL,
  checked_out_at    TEXT,
  latitude          REAL NOT NULL,
  longitude         REAL NOT NULL,
  accuracy_m        REAL,
  address           TEXT,
  within_geofence   INTEGER,
  distance_from_client_m REAL,
  duration_minutes  INTEGER NOT NULL DEFAULT 0,
  notes             TEXT,
  documents_collected INTEGER NOT NULL DEFAULT 0,
  photo_key         TEXT,
  created_at        TEXT NOT NULL
);
CREATE INDEX idx_visits_user ON gps_visits(user_id, checked_in_at);
CREATE INDEX idx_visits_client ON gps_visits(client_id, checked_in_at);

-- --------------------------------------------------------------------------
-- White label (add-on 24) — one branding row per tenant.
-- --------------------------------------------------------------------------
CREATE TABLE white_label_settings (
  tenant_id           TEXT PRIMARY KEY REFERENCES tenants(id) ON DELETE CASCADE,
  enabled             INTEGER NOT NULL DEFAULT 0,
  product_name        TEXT,
  logo_key            TEXT,
  logo_dark_key       TEXT,
  favicon_key         TEXT,
  app_icon_key        TEXT,
  primary_colour      TEXT,
  accent_colour       TEXT,
  sidebar_style       TEXT NOT NULL DEFAULT 'glass'
                        CHECK (sidebar_style IN ('glass','solid')),
  login_headline      TEXT,
  login_subtext       TEXT,
  login_image_key     TEXT,
  custom_domain       TEXT,
  domain_status       TEXT NOT NULL DEFAULT 'not_configured'
                        CHECK (domain_status IN ('not_configured','pending_dns','verifying','active','failed')),
  domain_verification_token TEXT,
  domain_verified_at  TEXT,
  ssl_status          TEXT NOT NULL DEFAULT 'none'
                        CHECK (ssl_status IN ('none','pending','active','failed')),
  email_from_name     TEXT,
  email_from_address  TEXT,
  email_footer        TEXT,
  sms_sender_id       TEXT,
  support_email       TEXT,
  support_phone       TEXT,
  hide_powered_by     INTEGER NOT NULL DEFAULT 0,
  updated_by          TEXT,
  updated_at          TEXT NOT NULL
);

-- --------------------------------------------------------------------------
-- Settings — namespaced key/value per tenant (and platform when tenant NULL).
-- --------------------------------------------------------------------------
CREATE TABLE settings (
  id            TEXT PRIMARY KEY,
  tenant_id     TEXT REFERENCES tenants(id) ON DELETE CASCADE,
  namespace     TEXT NOT NULL,          -- general | tax | storage | calling | notifications ...
  key           TEXT NOT NULL,
  value_json    TEXT NOT NULL,
  value_type    TEXT NOT NULL DEFAULT 'string'
                  CHECK (value_type IN ('string','number','boolean','json')),
  is_secret     INTEGER NOT NULL DEFAULT 0,
  description   TEXT,
  updated_by    TEXT,
  updated_at    TEXT NOT NULL
);
CREATE UNIQUE INDEX idx_settings_platform ON settings(namespace, key) WHERE tenant_id IS NULL;
CREATE UNIQUE INDEX idx_settings_tenant ON settings(tenant_id, namespace, key) WHERE tenant_id IS NOT NULL;

-- --------------------------------------------------------------------------
-- Feature flags — tenant-level overrides layered above plan and add-on gating.
-- --------------------------------------------------------------------------
CREATE TABLE feature_flags (
  id            TEXT PRIMARY KEY,
  tenant_id     TEXT REFERENCES tenants(id) ON DELETE CASCADE,
  feature_key   TEXT NOT NULL,
  enabled       INTEGER NOT NULL,
  reason        TEXT,
  expires_at    TEXT,
  created_by    TEXT,
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
);
CREATE UNIQUE INDEX idx_flags_platform ON feature_flags(feature_key) WHERE tenant_id IS NULL;
CREATE UNIQUE INDEX idx_flags_tenant ON feature_flags(tenant_id, feature_key) WHERE tenant_id IS NOT NULL;

-- --------------------------------------------------------------------------
-- Saved views — persisted table filters (§61: "filters must persist").
-- --------------------------------------------------------------------------
CREATE TABLE saved_views (
  id            TEXT PRIMARY KEY,
  tenant_id     TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  user_id       TEXT REFERENCES users(id) ON DELETE CASCADE,
  screen        TEXT NOT NULL,
  name          TEXT NOT NULL,
  filters_json  TEXT NOT NULL,
  columns_json  TEXT,
  sort_json     TEXT,
  is_default    INTEGER NOT NULL DEFAULT 0,
  is_shared     INTEGER NOT NULL DEFAULT 0,
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
);
CREATE INDEX idx_savedviews_user ON saved_views(user_id, screen);

-- --------------------------------------------------------------------------
-- Scheduled reports & exports (Advanced Analytics add-on)
-- --------------------------------------------------------------------------
CREATE TABLE scheduled_reports (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  name              TEXT NOT NULL,
  report_type       TEXT NOT NULL,
  filters_json      TEXT,
  format            TEXT NOT NULL DEFAULT 'csv' CHECK (format IN ('csv','pdf','json')),
  frequency         TEXT NOT NULL DEFAULT 'monthly'
                      CHECK (frequency IN ('daily','weekly','monthly','quarterly')),
  day_of_week       INTEGER,
  day_of_month      INTEGER,
  hour_utc          INTEGER NOT NULL DEFAULT 3,
  recipients_json   TEXT NOT NULL,
  is_active         INTEGER NOT NULL DEFAULT 1,
  last_run_at       TEXT,
  last_run_status   TEXT,
  next_run_at       TEXT,
  run_count         INTEGER NOT NULL DEFAULT 0,
  created_by        TEXT,
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL
);
CREATE INDEX idx_schedreports_next ON scheduled_reports(is_active, next_run_at);

-- --------------------------------------------------------------------------
-- Custom dashboards (Advanced Analytics add-on)
-- --------------------------------------------------------------------------
CREATE TABLE custom_dashboards (
  id            TEXT PRIMARY KEY,
  tenant_id     TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  user_id       TEXT REFERENCES users(id) ON DELETE CASCADE,
  name          TEXT NOT NULL,
  description   TEXT,
  widgets_json  TEXT NOT NULL,          -- [{type,metric,filters,span}]
  is_shared     INTEGER NOT NULL DEFAULT 0,
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
);

-- --------------------------------------------------------------------------
-- Push device registrations (Mobile App add-on)
-- --------------------------------------------------------------------------
CREATE TABLE push_tokens (
  id            TEXT PRIMARY KEY,
  tenant_id     TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  user_id       TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  token         TEXT NOT NULL,
  platform      TEXT NOT NULL CHECK (platform IN ('android','ios','web')),
  device_label  TEXT,
  app_version   TEXT,
  is_active     INTEGER NOT NULL DEFAULT 1,
  last_used_at  TEXT,
  created_at    TEXT NOT NULL,
  UNIQUE (user_id, token)
);

-- --------------------------------------------------------------------------
-- Offline capture queue (Mobile App: "offline document capture")
-- --------------------------------------------------------------------------
CREATE TABLE offline_captures (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  user_id           TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  client_id         TEXT REFERENCES clients(id) ON DELETE SET NULL,
  local_ref         TEXT NOT NULL,
  document_type_id  TEXT,
  file_name         TEXT,
  size_bytes        INTEGER,
  captured_at       TEXT NOT NULL,
  status            TEXT NOT NULL DEFAULT 'pending'
                      CHECK (status IN ('pending','uploading','uploaded','failed','discarded')),
  document_id       TEXT REFERENCES documents(id) ON DELETE SET NULL,
  error_message     TEXT,
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL,
  UNIQUE (user_id, local_ref)
);

-- --------------------------------------------------------------------------
-- Rate limiting — durable counters (KV is the fast path, this is the record)
-- --------------------------------------------------------------------------
CREATE TABLE rate_limits (
  id            TEXT PRIMARY KEY,       -- bucket key
  scope         TEXT NOT NULL,
  window_start  TEXT NOT NULL,
  count         INTEGER NOT NULL DEFAULT 0,
  expires_at    TEXT NOT NULL
);
CREATE INDEX idx_ratelimits_expiry ON rate_limits(expires_at);

-- ===== 0009_permission_override_metadata.sql =====

-- Per-user permission overrides: why, and for how long.
--
-- An elevated permission that nobody can explain, and that never expires, is
-- how an organisation quietly accumulates over-privileged accounts. The reason
-- is recorded so an auditor can read it, and the expiry is enforced where
-- permissions are loaded (src/auth/identity.js), not merely displayed.

ALTER TABLE user_permissions ADD COLUMN reason TEXT;
ALTER TABLE user_permissions ADD COLUMN expires_at TEXT;

CREATE INDEX idx_user_permissions_expiry
  ON user_permissions (expires_at) WHERE expires_at IS NOT NULL;

-- ===== 0010_oauth_state_hash.sql =====

-- Store only the hash of an OAuth state value.
--
-- The state is the one thing standing between a stolen authorisation code and
-- a linked account, so the database should not hold a value that could be
-- replayed as a valid callback. The column is renamed rather than shadowed so
-- its name says what it holds.

ALTER TABLE oauth_states RENAME COLUMN state TO state_hash;

-- ===== 0011_chatbot_thread_state.sql =====

-- ---------------------------------------------------------------------------
-- 0011 — Chatbot conversation state on a chat thread.
--
-- `chatbot_flows` has existed since 0005 but nothing could read or write it:
-- there was no API, no screen, and no way for an inbound message to enter a
-- flow. These three columns are what a thread needs to remember where it is in
-- one, so the bot can pick up a conversation on the next message instead of
-- starting over.
--
-- All three are nullable with sane defaults, so existing threads are unchanged
-- and behave exactly as before: no flow, no handover, nothing automated.
-- ---------------------------------------------------------------------------

-- The flow this thread is currently inside, if any. NULL means the bot is not
-- driving this conversation.
ALTER TABLE chat_threads ADD COLUMN bot_flow_id TEXT REFERENCES chatbot_flows(id) ON DELETE SET NULL;

-- Which node of that flow the thread is waiting at.
ALTER TABLE chat_threads ADD COLUMN bot_node_id TEXT;

-- Set once the bot has given up and a person is expected. It stays set so the
-- bot does not re-enter a conversation somebody has already taken over.
ALTER TABLE chat_threads ADD COLUMN bot_handed_over INTEGER NOT NULL DEFAULT 0;

CREATE INDEX idx_chatthreads_bot ON chat_threads(tenant_id, bot_flow_id);

-- ===== 0012_automation_runs_and_queues.sql =====

-- ---------------------------------------------------------------------------
-- 0012 — Make automation and broadcasts actually run.
--
-- Two features shipped with a table, a screen and an API, and no execution:
--
--   * automation_rules could be written and listed, but nothing ever evaluated
--     them, so fire_count stayed 0 for ever and a "wait 2 days then remind"
--     rule was a row nobody read.
--   * broadcasts were inserted with status 'queued' — a value the CHECK
--     constraint on that table does not allow, so an immediate broadcast
--     failed outright, and a scheduled one was stored and never sent.
--
-- What execution needs that the schema did not have:
--
--   automation_jobs   — a due-time queue, so a delayed rule survives the
--                       request that triggered it and runs later.
--   automation_runs   — what happened, per rule per event. Without it a
--                       failing rule is invisible: fire_count only counts
--                       successes, and the error went to console.warn.
--   broadcast_recipients — one row per recipient, so delivery is tracked per
--                       person rather than as a count nobody can audit, and
--                       so a retry does not re-send to those already reached.
--
-- The broadcasts.status CHECK is also widened. SQLite cannot alter a CHECK in
-- place, so the table is rebuilt; existing rows are carried over.
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- Delayed automation
-- ---------------------------------------------------------------------------
CREATE TABLE automation_jobs (
  id            TEXT PRIMARY KEY,
  tenant_id     TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  rule_id       TEXT NOT NULL REFERENCES automation_rules(id) ON DELETE CASCADE,
  trigger_key   TEXT NOT NULL,
  payload_json  TEXT,
  run_after     TEXT NOT NULL,
  status        TEXT NOT NULL DEFAULT 'pending'
                  CHECK (status IN ('pending','running','done','failed','cancelled')),
  attempts      INTEGER NOT NULL DEFAULT 0,
  last_error    TEXT,
  -- Set from the event that queued the job. Two identical events for the same
  -- rule and entity must not queue the work twice; the unique index below is
  -- what enforces that.
  dedupe_key    TEXT,
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
);
CREATE INDEX idx_autojobs_due ON automation_jobs(status, run_after);
CREATE INDEX idx_autojobs_tenant ON automation_jobs(tenant_id, rule_id);
CREATE UNIQUE INDEX idx_autojobs_dedupe ON automation_jobs(rule_id, dedupe_key)
  WHERE dedupe_key IS NOT NULL AND status IN ('pending','running');

-- ---------------------------------------------------------------------------
-- What each rule actually did
-- ---------------------------------------------------------------------------
CREATE TABLE automation_runs (
  id            TEXT PRIMARY KEY,
  tenant_id     TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  rule_id       TEXT NOT NULL REFERENCES automation_rules(id) ON DELETE CASCADE,
  trigger_key   TEXT NOT NULL,
  -- fired    — conditions matched and every action ran
  -- skipped  — conditions did not match; this is a normal outcome, not a fault
  -- queued   — a delayed rule; the automation_jobs row carries it from here
  -- failed   — an action threw. last_error says what.
  status        TEXT NOT NULL
                  CHECK (status IN ('fired','skipped','queued','failed')),
  reason        TEXT,
  actions_json  TEXT,
  error         TEXT,
  entity_type   TEXT,
  entity_id     TEXT,
  created_at    TEXT NOT NULL
);
CREATE INDEX idx_autoruns_rule ON automation_runs(rule_id, created_at);
CREATE INDEX idx_autoruns_tenant ON automation_runs(tenant_id, created_at);

-- ---------------------------------------------------------------------------
-- Broadcast delivery, per recipient
-- ---------------------------------------------------------------------------
CREATE TABLE broadcast_recipients (
  id            TEXT PRIMARY KEY,
  tenant_id     TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  broadcast_id  TEXT NOT NULL REFERENCES broadcasts(id) ON DELETE CASCADE,
  client_id     TEXT REFERENCES clients(id) ON DELETE SET NULL,
  user_id       TEXT REFERENCES users(id) ON DELETE SET NULL,
  to_address    TEXT NOT NULL,
  status        TEXT NOT NULL DEFAULT 'pending'
                  CHECK (status IN ('pending','sent','delivered','failed','skipped')),
  provider_message_id TEXT,
  error         TEXT,
  attempts      INTEGER NOT NULL DEFAULT 0,
  sent_at       TEXT,
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
);
CREATE INDEX idx_bcastrcpt_broadcast ON broadcast_recipients(broadcast_id, status);
CREATE INDEX idx_bcastrcpt_tenant ON broadcast_recipients(tenant_id);
CREATE UNIQUE INDEX idx_bcastrcpt_unique ON broadcast_recipients(broadcast_id, to_address);

-- ---------------------------------------------------------------------------
-- Widen broadcasts.status
--
-- The old CHECK allowed draft/scheduled/sending/completed/failed/cancelled.
-- The code inserts 'queued' and needs 'processing' and 'sent' for the
-- lifecycle to be describable. SQLite has no ALTER for a CHECK, so: rebuild.
-- ---------------------------------------------------------------------------
CREATE TABLE broadcasts_new (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  channel           TEXT NOT NULL CHECK (channel IN ('whatsapp','sms','email')),
  name              TEXT NOT NULL,
  template_id       TEXT REFERENCES whatsapp_templates(id) ON DELETE SET NULL,
  body              TEXT,
  audience_json     TEXT NOT NULL,
  recipient_count   INTEGER NOT NULL DEFAULT 0,
  sent_count        INTEGER NOT NULL DEFAULT 0,
  delivered_count   INTEGER NOT NULL DEFAULT 0,
  failed_count      INTEGER NOT NULL DEFAULT 0,
  status            TEXT NOT NULL DEFAULT 'draft'
                      CHECK (status IN ('draft','queued','scheduled','processing','sending','sent','completed','failed','cancelled')),
  scheduled_at      TEXT,
  started_at        TEXT,
  completed_at      TEXT,
  last_error        TEXT,
  created_by        TEXT REFERENCES users(id) ON DELETE SET NULL,
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL
);

INSERT INTO broadcasts_new
  (id, tenant_id, channel, name, template_id, body, audience_json, recipient_count,
   sent_count, delivered_count, failed_count, status, scheduled_at, started_at,
   completed_at, created_by, created_at, updated_at)
SELECT
   id, tenant_id, channel, name, template_id, body, audience_json, recipient_count,
   sent_count, delivered_count, failed_count, status, scheduled_at, started_at,
   completed_at, created_by, created_at, updated_at
FROM broadcasts;

DROP TABLE broadcasts;
ALTER TABLE broadcasts_new RENAME TO broadcasts;
CREATE INDEX idx_broadcasts_tenant ON broadcasts(tenant_id, status, created_at);

-- ===== 0015_platform_support_access.sql =====

-- ---------------------------------------------------------------------------
-- 0015 — platform support access and the subscription lifecycle ledger.
--
-- Support access: a session the platform Super Admin opens inside an
-- organisation must carry who really holds it, so the original identity is
-- never lost, actions are attributed to the administrator (not the person
-- they act as), and view-only mode can be enforced server-side. The label is
-- frozen at mint time so audit attribution never depends on a later lookup.
--
-- Lifecycle: subscription changes need a history that outlives audit-log
-- retention — what plan an organisation was on, when a period was extended,
-- when a reminder was sent, when a payment was recorded by the platform.
-- One append-only ledger covers all of it.
-- ---------------------------------------------------------------------------

ALTER TABLE sessions ADD COLUMN impersonator_user_id TEXT REFERENCES users(id) ON DELETE SET NULL;
ALTER TABLE sessions ADD COLUMN impersonator_label TEXT;
ALTER TABLE sessions ADD COLUMN impersonation_mode TEXT
  CHECK (impersonation_mode IN ('view','support') OR impersonation_mode IS NULL);

-- The dunning window after a missed renewal or an ended trial: past_due until
-- this moment, expired after it.
ALTER TABLE subscriptions ADD COLUMN grace_until TEXT;

CREATE TABLE subscription_events (
  id              TEXT PRIMARY KEY,
  tenant_id       TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  subscription_id TEXT REFERENCES subscriptions(id) ON DELETE SET NULL,
  kind            TEXT NOT NULL
                    CHECK (kind IN ('plan_changed','period_extended','trial_extended','status_changed',
                                    'payment_recorded','reminder_sent','renewed','suspended','reactivated','note')),
  actor_id        TEXT,
  actor_name      TEXT,
  old_value_json  TEXT,
  new_value_json  TEXT,
  note            TEXT,
  created_at      TEXT NOT NULL
);
CREATE INDEX idx_subevents_tenant ON subscription_events(tenant_id, created_at);
